  IF (SELECT COUNT(*) FROM repository_validation_results v JOIN repository_revisions r ON r.revision_id=v.revision_id
      WHERE r.revision_code='RKB1-REV-CH1-RELEASED-2026-10-19'
        AND v.validation_code='RKB1-50-CHAPTER_FINAL_GATE'
        AND v.validation_status='passed' AND BINARY v.actual_value='RELEASED')<>1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH PRESTATE FAIL: CH1_RELEASE'; END IF;
  IF (SELECT COUNT(*) FROM documents WHERE file_name='Kapitel_1_Einleitung_Literatur_nach_Erstnennung_2026-10-17.docx'
