    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH PRESTATE FAIL: CH1_HASH'; END IF;
  IF (SELECT COUNT(*) FROM source_authors sa JOIN sources s ON s.source_id=sa.source_id WHERE s.citation_number BETWEEN 1 AND 14)<>15 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH PRESTATE FAIL: CH1_AUTHOR_LINKS'; END IF;
  IF (SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 15 AND 31)<>17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH PRESTATE FAIL: SOURCE_COUNT'; END IF;
  IF (SELECT COUNT(*) FROM (SELECT DISTINCT citation_number,source_key FROM tmp_rkb2_author_map) m
