  IF EXISTS (
      SELECT 1 FROM source_authors sa JOIN sources s ON s.source_id=sa.source_id
      JOIN authors a ON a.author_id=sa.author_id
      WHERE s.citation_number BETWEEN 15 AND 31 AND NOT EXISTS (
          SELECT 1 FROM tmp_rkb2_author_map m
          WHERE m.citation_number=s.citation_number
            AND m.role=sa.role AND m.author_order=sa.author_order
            AND BINARY m.normalized_name=BINARY a.normalized_name
      )
  ) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH PRESTATE FAIL: EXISTING_LINK_CONFLICT'; END IF;

  SELECT revision_id INTO v_previous FROM repository_revisions
