  VALUES ('RKB2-REV-CH2-AUTHORS-15-31-2026-10-19',NOW(),'source','15-31','ch2-authors-correction-v1',
          'Autorenstammdaten und geordnete Quellenzuordnungen fuer Kapitel 2.0-2.1 nachmaterialisiert. Keine Kapitel-1-Aenderung und keine wissenschaftliche Gesamtfreigabe.',
          'FRZK / bibliografische Korrektur',v_previous);
  SET v_revision=LAST_INSERT_ID();

  -- Vorberechnete Differenzmengen vermeiden MySQL/MariaDB-Fehler #1093
  -- (Lesezugriff auf eigene INSERT-Zieltabelle).
  DROP TEMPORARY TABLE IF EXISTS tmp_rkb2_missing_authors;
  CREATE TEMPORARY TABLE tmp_rkb2_missing_authors ENGINE=InnoDB AS
  SELECT DISTINCT t.family_name,t.given_names,t.normalized_name,
         CASE WHEN t.citation_number=29 THEN 'Institutioneller Urheber / Normgeber IEEE Std 754-2019'
              ELSE NULL END AS notes
  FROM tmp_rkb2_author_map t LEFT JOIN authors a ON a.normalized_name=t.normalized_name
  WHERE a.author_id IS NULL;
