  INSERT INTO authors (family_name,given_names,normalized_name,notes)
  SELECT family_name,given_names,normalized_name,notes FROM tmp_rkb2_missing_authors;
  SET v_new_authors=ROW_COUNT();

  DROP TEMPORARY TABLE IF EXISTS tmp_rkb2_missing_links;
  CREATE TEMPORARY TABLE tmp_rkb2_missing_links ENGINE=InnoDB AS
  SELECT s.source_id,a.author_id,t.author_order,t.role
  FROM tmp_rkb2_author_map t
  JOIN sources s ON s.citation_number=t.citation_number AND BINARY s.source_key=BINARY t.source_key
  JOIN authors a ON a.normalized_name=t.normalized_name
  LEFT JOIN source_authors sa ON sa.source_id=s.source_id AND sa.author_id=a.author_id AND sa.role=t.role
  WHERE sa.source_id IS NULL;
  INSERT INTO source_authors (source_id,author_id,author_order,role)
  SELECT source_id,author_id,author_order,role FROM tmp_rkb2_missing_links;
  SET v_new_links=ROW_COUNT();

  -- Strenger Abschluss gegen falsch zugeordnete, fehlende, doppelte Links.
  IF (SELECT COUNT(*) FROM source_authors sa JOIN sources s ON s.source_id=sa.source_id
      WHERE s.citation_number BETWEEN 15 AND 31)<>v_expected THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH POSTCONDITION FAIL: LINK_COUNT'; END IF;
  IF (SELECT COUNT(*) FROM tmp_rkb2_author_map m
      JOIN sources s ON s.citation_number=m.citation_number AND BINARY s.source_key=BINARY m.source_key
      JOIN authors a ON a.normalized_name=m.normalized_name
      JOIN source_authors sa ON sa.source_id=s.source_id AND sa.author_id=a.author_id
           AND sa.author_order=m.author_order AND sa.role=m.role)<>v_expected THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH POSTCONDITION FAIL: ORDER_OR_ROLE'; END IF;
  IF (SELECT COUNT(*) FROM source_authors sa JOIN sources s ON s.source_id=sa.source_id
      WHERE s.citation_number BETWEEN 1 AND 14)<>15 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH POSTCONDITION FAIL: CH1_LINKS'; END IF;

  INSERT INTO repository_validation_results
  (revision_id,validation_code,validation_status,expected_value,actual_value,validation_message)
  VALUES
  (v_revision,'RKB2-AUTH-SOURCES','passed','17 sources, citation numbers 15-31','17','Identitaeten und source_keys unveraendert referenziert.'),
  (v_revision,'RKB2-AUTH-MAPPING','passed','52 bibliographic contributor links','52','Quellen, Urheberreihenfolge und Rollen sind vollstaendig geprueft.'),
  (v_revision,'RKB2-AUTH-EDITORS','passed','27 two editors','2','Lesh und Doerr als Herausgeber verknuepft.'),
  (v_revision,'RKB2-AUTH-IEEE','passed','29 corporate author','1','IEEE als Koerperschaft, nicht als erfundene Einzelperson.'),
  (v_revision,'RKB2-AUTH-PRISMA','passed','18: 26 contributors','26','Vollstaendige BMJ-Autorenliste zum DOI 10.1136/bmj.n71.'),
  (v_revision,'RKB2-AUTH-CH1-PROTECTED','passed','15 chapter-1 author links','15','Kapitel 1 und sein Freigabesnapshot unveraendert.'),
  (v_revision,'RKB2-AUTH-CONTENT-REVIEW','warning','Originalstellen und Claims wissenschaftlich geprueft','OPEN','Diese Korrektur repariert die Autorenrelation, nicht die inhaltliche Belegpruefung.'),
  (v_revision,'RKB2-AUTH-FINAL-GATE','warning','RELEASED','NOT_RELEASED','Kapitel 2 bleibt DRAFT.');
  IF (SELECT COUNT(*) FROM repository_validation_results WHERE revision_id=v_revision)<>8 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AUTH POSTCONDITION FAIL: VALIDATION_COUNT'; END IF;
  COMMIT;
  SELECT 'MATERIALIZATION' AS check_code,'PASS' AS result,
         v_new_authors AS newly_created_authors, v_new_links AS newly_created_links,
         52 AS expected_total_links, v_revision AS correction_revision_id;
  DROP TEMPORARY TABLE IF EXISTS tmp_rkb2_missing_links;
  DROP TEMPORARY TABLE IF EXISTS tmp_rkb2_missing_authors;
  DROP TEMPORARY TABLE IF EXISTS tmp_rkb2_author_map;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_final_gate_20261021` ()   BEGIN
  DECLARE v_n INT DEFAULT 0;
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_status VARCHAR(40);
  DECLARE v_total INT DEFAULT 0;
  DECLARE v_fail INT DEFAULT 0;
  DECLARE v_missing INT DEFAULT 0;
  DECLARE v_duplicates INT DEFAULT 0;
  DECLARE v_open INT DEFAULT 0;

  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
  BEGIN
    -- Exceptions do not silently release; the procedure itself fails.
    RESIGNAL;
  END;

  CREATE TEMPORARY TABLE IF NOT EXISTS `tmp_rkb2_final_gate` (
    `gate_name` varchar(90) NOT NULL PRIMARY KEY,
    `result` enum('PASS','FAIL','INFO') NOT NULL,
    `actual_value` varchar(255),
    `expected_value` varchar(255),
    `details` text
  ) ENGINE=InnoDB;
  TRUNCATE TABLE `tmp_rkb2_final_gate`;

  -- 1. Kapitelwurzel und exakter Abschnittsplan 2.0 ... 2.10
  SELECT COUNT(*) INTO v_n FROM dissertation_sections WHERE section_code='2';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('01_CH2_ROOT', IF(v_n=1,'PASS','FAIL'),v_n,'1','Eindeutige Kapitelwurzel 2');

  SELECT COUNT(*) INTO v_n
  FROM dissertation_sections
  WHERE chapter_no=2 AND section_code REGEXP '^2\\.(0|[1-9]|10)$';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('02_SECTIONS_11',IF(v_n=11,'PASS','FAIL'),v_n,'11','Abschnitte 2.0 bis 2.10 vorhanden');

  SELECT COUNT(*) INTO v_missing FROM (
    SELECT '2.0' AS code UNION ALL SELECT '2.1' UNION ALL SELECT '2.2'
    UNION ALL SELECT '2.3' UNION ALL SELECT '2.4' UNION ALL SELECT '2.5'
    UNION ALL SELECT '2.6' UNION ALL SELECT '2.7' UNION ALL SELECT '2.8'
    UNION ALL SELECT '2.9' UNION ALL SELECT '2.10'
  ) p LEFT JOIN dissertation_sections s ON s.section_code=p.code
  WHERE s.section_id IS NULL;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('03_NO_MISSING_SECTION',IF(v_missing=0,'PASS','FAIL'),v_missing,'0','Lueckenfreier Soll-Abschnittsplan');

  SELECT COUNT(*) INTO v_n
  FROM dissertation_sections s
  JOIN dissertation_sections root ON root.section_code='2'
  WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$'
    AND s.parent_section_id=root.section_id;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('04_SECTION_HIERARCHY',IF(v_n=11,'PASS','FAIL'),v_n,'11','Alle Unterabschnitte direkt unter Kapitel 2');

  SELECT COUNT(*) INTO v_n
  FROM dissertation_sections
  WHERE (section_code='2' OR section_code REGEXP '^2\\.(0|[1-9]|10)$')
    AND status='final';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('05_ALL_FINAL_STATUS',IF(v_n=12,'PASS','FAIL'),v_n,'12','Wurzel und 11 Abschnitte final; DRAFT/REVIEW/PLANNED ist nicht RELEASED');

  -- 2. Versionstabelle nur pruefen, falls sie wirklich existiert.
  SELECT COUNT(*) INTO v_n FROM information_schema.TABLES
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='section_versions'
    AND TABLE_TYPE='BASE TABLE';
  IF v_n=1 THEN
  -- 2. Je Abschnitt gilt die letzte gespeicherte Version als massgeblich.
  -- Keine Ueberschreibung durch fruehere Chatfassungen.
  SELECT COUNT(*) INTO v_n FROM (
    SELECT s.section_id, MAX(v.section_version_id) AS version_id
    FROM dissertation_sections s
    LEFT JOIN section_versions v ON v.section_id=s.section_id
    WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$'
    GROUP BY s.section_id
  ) q WHERE q.version_id IS NOT NULL;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('06_11_LATEST_VERSIONS',IF(v_n=11,'PASS','FAIL'),v_n,'11','Je Abschnitt existiert mindestens eine gespeicherte Version');

  SELECT COUNT(*) INTO v_n
  FROM dissertation_sections s
  JOIN section_versions v ON v.section_id=s.section_id
  JOIN (SELECT section_id,MAX(section_version_id) AS max_id
        FROM section_versions GROUP BY section_id) last_v
    ON last_v.section_id=v.section_id AND last_v.max_id=v.section_version_id
  WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$'
    AND v.body_markdown IS NOT NULL
    AND CHAR_LENGTH(TRIM(v.body_markdown)) >= 300;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('07_LATEST_TEXT_NONEMPTY',IF(v_n=11,'PASS','FAIL'),v_n,'11','Neueste Textfassungen mit Mindestinhalt (300 Zeichen)');

  SELECT COUNT(*) INTO v_n
  FROM dissertation_sections s
  JOIN section_versions v ON v.section_id=s.section_id
  JOIN (SELECT section_id,MAX(section_version_id) AS max_id
        FROM section_versions GROUP BY section_id) last_v
    ON last_v.section_id=v.section_id AND last_v.max_id=v.section_version_id
  WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$'
    AND v.checksum_sha256 IS NOT NULL
    AND LOWER(v.checksum_sha256)=LOWER(SHA2(v.body_markdown,256));
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('08_LATEST_SHA256_MATCH',IF(v_n=11,'PASS','FAIL'),v_n,'11','Persistierter Hash entspricht Byteinhalt der letzten Version');

  SELECT COUNT(*) INTO v_n
  FROM dissertation_sections s
  JOIN section_versions v ON v.section_id=s.section_id
  JOIN (SELECT section_id,MAX(section_version_id) AS max_id
        FROM section_versions GROUP BY section_id) last_v
    ON last_v.section_id=v.section_id AND last_v.max_id=v.section_version_id
  WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$'
    AND v.version_kind='final';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('09_11_LATEST_FINAL_VERSIONS',IF(v_n=11,'PASS','FAIL'),v_n,'11','Letzte Importfassung nur dann freigegeben, wenn als final markiert');

  ELSE
    INSERT INTO tmp_rkb2_final_gate VALUES
    ('06_11_LATEST_VERSIONS','FAIL','Tabelle fehlt','11','section_versions fehlt: Versionsnachweis nicht moeglich'),
    ('07_LATEST_TEXT_NONEMPTY','FAIL','nicht pruefbar','11','Kein Versionsinhalt verfuegbar'),
    ('08_LATEST_SHA256_MATCH','FAIL','nicht pruefbar','11','Kein SHA256-Versionsnachweis verfuegbar'),
    ('09_11_LATEST_FINAL_VERSIONS','FAIL','nicht pruefbar','11','Kein Final-Versionsnachweis verfuegbar');
  END IF;

  -- 3. Literatur: Vollstaendigkeit, Nummerneindeutigkeit, Metadaten
  SELECT COUNT(*) INTO v_n FROM sources WHERE citation_number BETWEEN 15 AND 149;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('10_SOURCES_135',IF(v_n=135,'PASS','FAIL'),v_n,'135','Quellen [15]-[149], Kapitel-2-Sollbestand');

  SELECT COUNT(*) INTO v_duplicates FROM (
    SELECT citation_number FROM sources WHERE citation_number BETWEEN 15 AND 149
    GROUP BY citation_number HAVING COUNT(*)<>1
  ) d;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('11_CITATION_UNIQUE',IF(v_duplicates=0,'PASS','FAIL'),v_duplicates,'0','Keine doppelt belegte Nummer');

  SELECT COUNT(*) INTO v_n
  FROM sources WHERE citation_number BETWEEN 15 AND 149
    AND TRIM(COALESCE(title,''))<>''
    AND TRIM(COALESCE(full_citation_text,''))<>''
    AND year_edition IS NOT NULL;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('12_CITATION_CORE_COMPLETE',IF(v_n=135,'PASS','FAIL'),v_n,'135',
     'Titel, Vollzitat und Editionsjahr vorhanden; ISBN/DOI koennen sachlich nicht anwendbar sein');

  SELECT COUNT(*) INTO v_n FROM sources
  WHERE citation_number BETWEEN 15 AND 149
    AND (NULLIF(TRIM(doi),'') IS NULL);
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('13_MISSING_DOI_INFORMATION','INFO',v_n,'kein Grenzwert','Fehlender DOI ist fuer historische Buecher und andere Werke kein automatischer Fehler');

  SELECT COUNT(*) INTO v_n
  FROM sources WHERE citation_number BETWEEN 15 AND 149
    AND NULLIF(TRIM(doi),'') IS NOT NULL
    AND (url IS NULL OR TRIM(url)='');
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('14_DOI_RESOLVER_LINKS',IF(v_n=0,'PASS','FAIL'),v_n,'0',
     'DOI-tragende Datensaetze benoetigen eine belegte URL; Literaturreparatur zuerst ausfuehren');

  SELECT COUNT(*) INTO v_n FROM sources
  WHERE citation_number BETWEEN 15 AND 149
    AND verification_status='verified';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('15_SOURCE_VERIFICATION_135',IF(v_n=135,'PASS','FAIL'),v_n,'135',
     'Bibliografische und konkrete Originalstellen-/Claimpruefung muss separat abgeschlossen sein');

  SELECT COUNT(*) INTO v_n
  FROM sources WHERE citation_number IN (90,94,95,117,139)
    AND NULLIF(TRIM(isbn),'') IS NOT NULL
    AND NULLIF(TRIM(url),'') IS NOT NULL;
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('16_FIVE_EDITION_RECORDS',IF(v_n=5,'PASS','FAIL'),v_n,'5',
     'ISBN und URL fuer die fuenf editionskritischen Quellen hinterlegt');

  SELECT COUNT(*) INTO v_n FROM sources
  WHERE citation_number=90 AND pages='10–51'
    AND isbn='978-90-329-2334-1';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('17_PLOMP_PAGES',IF(v_n=1,'PASS','FAIL'),v_n,'1','Plomp 2013, S. 10–51, Ausgabe eindeutig');

  -- 4. Gleichungen - wenn vorhanden, kein leerer Word-LaTeX-Nachweis
  SELECT COUNT(*) INTO v_n
  FROM equations e JOIN dissertation_sections s ON e.section_id=s.section_id
  WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$'
    AND (TRIM(COALESCE(e.word_latex,''))=''
         OR TRIM(COALESCE(e.equation_latex,''))=''
         OR TRIM(COALESCE(e.plain_description,''))='');
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('18_EQUATIONS_RENDER_AND_WORD',IF(v_n=0,'PASS','FAIL'),v_n,'0',
     'Registrierte Gleichungen brauchen Satzquelle, Word-LaTeX und Erklaerung');

  -- 5. Keine stillschweigende Freigabe: explizite autorisierte Kapitelentscheidung.
  -- Das Gate kann eine wissenschaftliche Autorenentscheidung NICHT selbst erzeugen.
  SELECT COUNT(*) INTO v_n
  FROM repository_validation_results vr
  JOIN repository_revisions r ON r.revision_id=vr.revision_id
  WHERE r.scope_reference='2'
    AND vr.validation_code='CH2_AUTHOR_APPROVAL_PASS'
    AND vr.validation_status='passed';
  INSERT INTO tmp_rkb2_final_gate VALUES
    ('19_AUTHOR_APPROVAL',IF(v_n>0,'PASS','FAIL'),v_n,'>=1',
     'Explizite Autorfreigabe im Repository; wird durch dieses Skript nicht erzeugt');

  SELECT COUNT(*) INTO v_fail FROM tmp_rkb2_final_gate WHERE result='FAIL';
  SET v_status=IF(v_fail=0,'RELEASE_CANDIDATE','BLOCKED');

  DELETE FROM rkb2_ch2_gate_results_20261021;
  INSERT INTO rkb2_ch2_gate_results_20261021
  (gate_name,result,actual_value,expected_value,details)
  SELECT gate_name,result,actual_value,expected_value,details FROM tmp_rkb2_final_gate;
  INSERT INTO rkb2_ch2_gate_results_20261021
  (gate_name,result,actual_value,expected_value,details)
  VALUES ('20_OVERALL',IF(v_fail=0,'PASS','FAIL'),v_status,'RELEASE_CANDIDATE',
  'Gesamtstatus. RELEASE_CANDIDATE ist keine Autorenfreigabe.');

  DROP TEMPORARY TABLE IF EXISTS tmp_rkb2_final_gate;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_final_release` ()   BEGIN
DECLARE v_parent BIGINT UNSIGNED DEFAULT NULL;
DECLARE v_rev BIGINT UNSIGNED DEFAULT NULL;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
START TRANSACTION;
IF NOT ((SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND section_code LIKE '2.%' AND status='draft')=11) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_01'; END IF;
IF NOT ((SELECT COUNT(*) FROM dissertation_sections WHERE section_code='2' AND status='draft')=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_02'; END IF;
IF NOT ((SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 1 AND 149)=149) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_03'; END IF;
IF NOT ((SELECT COUNT(*) FROM source_authors sa JOIN sources s ON s.source_id=sa.source_id WHERE s.citation_number BETWEEN 1 AND 149)=284) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_04'; END IF;
IF NOT ((SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections s ON s.section_id=u.section_id WHERE s.chapter_no=2 AND s.section_code LIKE '2.%' AND u.citation_checked=0)=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_05'; END IF;
IF NOT ((SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id JOIN sources s ON s.source_id=u.source_id WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND s.verification_status<>'verified')=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_06'; END IF;
IF NOT ((SELECT COUNT(*) FROM repository_revisions WHERE revision_code='RKB2-REV-CH2-REVIEW-2026-10-20')=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_07'; END IF;
IF NOT ((SELECT COUNT(*) FROM repository_validation_results v JOIN repository_revisions r ON r.revision_id=v.revision_id WHERE r.revision_code='RKB2-REV-CH2-REVIEW-2026-10-20' AND v.validation_status='passed' AND BINARY v.actual_value='VERIFIED' AND v.validation_code IN ('RKB2-CH2-SOURCE_ORIGINALS','RKB2-CH2-CLAIM_BY_CLAIM','RKB2-CH2-RESEARCH_PROTOCOL','RKB2-CH2-BIBLIOGRAPHY_EDITION','RKB2-CH2-MATH_SCOPE','RKB2-CH2-DIDACTIC_SCOPE','RKB2-CH2-TEXT_IDENTITY_0','RKB2-CH2-TEXT_IDENTITY_1','RKB2-CH2-TEXT_IDENTITY_2','RKB2-CH2-TEXT_IDENTITY_3','RKB2-CH2-TEXT_IDENTITY_4','RKB2-CH2-TEXT_IDENTITY_5','RKB2-CH2-TEXT_IDENTITY_6','RKB2-CH2-TEXT_IDENTITY_7','RKB2-CH2-TEXT_IDENTITY_8','RKB2-CH2-TEXT_IDENTITY_9','RKB2-CH2-TEXT_IDENTITY_10'))=17) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_08'; END IF;
IF NOT ((SELECT COUNT(*) FROM repository_validation_results v JOIN repository_revisions r ON r.revision_id=v.revision_id WHERE r.revision_code='RKB2-REV-CH2-REVIEW-2026-10-20' AND v.validation_status='warning')=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_09'; END IF;
IF NOT ((SELECT COUNT(*) FROM (SELECT LOWER(doi) AS d, COUNT(*) AS n FROM sources WHERE citation_number BETWEEN 1 AND 149 AND doi IS NOT NULL AND doi<>'' GROUP BY LOWER(doi) HAVING COUNT(*)>1) t)=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_10'; END IF;
IF NOT ((SELECT COUNT(*) FROM repository_revisions WHERE revision_code='RKB2-REV-CH2-RELEASED-2026-10-20')=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_11'; END IF;
IF NOT ((SELECT COUNT(*) FROM repository_validation_results v JOIN repository_revisions r ON r.revision_id=v.revision_id WHERE r.revision_code='RKB1-REV-CH1-RELEASED-2026-10-19' AND v.validation_code='RKB1-50-CHAPTER_FINAL_GATE' AND v.validation_status='passed' AND BINARY v.actual_value='RELEASED')=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL BLOCKED: GATE_12'; END IF;
SELECT revision_id INTO v_parent FROM repository_revisions WHERE revision_code='RKB2-REV-CH2-REVIEW-2026-10-20' LIMIT 1;
INSERT INTO repository_revisions (revision_code,revision_date,scope_type,scope_reference,version_label,summary,created_by,parent_revision_id) VALUES ('RKB2-REV-CH2-RELEASED-2026-10-20',NOW(),'chapter','2','ch2-released-v1','Fachlich bestaetigte Endfassung Kapitel 2 nach 17 Review-Gates und Quellenpruefung.','FRZK / externe Fachfreigabe',v_parent);
SET v_rev=LAST_INSERT_ID();
UPDATE dissertation_sections SET status='final' WHERE chapter_no=2 AND section_code LIKE '2.%' AND status='draft';
IF ROW_COUNT()<>11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL FAIL: SECTION_COUNT'; END IF;
UPDATE dissertation_sections SET status='final' WHERE section_code='2' AND status='draft';
IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL FAIL: ROOT'; END IF;
INSERT INTO repository_validation_results (revision_id,validation_code,validation_status,expected_value,actual_value,validation_message) VALUES (v_rev,'RKB2-CH2-FINAL-GATE','passed','RELEASED','RELEASED','Freigabe nach extern dokumentierter Originalstellenpruefung, Volltextabgleich und fachlichem Review.');
IF NOT ((SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND section_code LIKE '2.%' AND status='final')=11 AND (SELECT COUNT(*) FROM dissertation_sections WHERE section_code='2' AND status='final')=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CH2 FINAL POSTSTATE FAIL'; END IF;
COMMIT;
SELECT 'CH2_FINAL_GATE' AS check_code,'RELEASED' AS result,v_rev AS revision_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_20` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135
     OR (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PRECHECK 2.0: AUDIT REGISTER COUNT CHANGED';
  END IF;
  IF (SELECT COUNT(*) FROM sources s JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
      WHERE s.citation_number BETWEEN 15 AND 18)<>4 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PRECHECK 2.0: SOURCE ROWS NOT UNIQUE';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
      JOIN sources s ON s.source_id=u.source_id JOIN dissertation_sections d ON d.section_id=u.section_id
      WHERE d.section_code='2.0' AND s.citation_number BETWEEN 15 AND 18)<>4 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PRECHECK 2.0: CLAIM ROWS NOT UNIQUE';
  END IF;
  IF EXISTS (
    SELECT 1 FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
    WHERE s.citation_number BETWEEN 15 AND 18 AND
    (r.review_status NOT IN ('open','in_review') OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
     OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))
  ) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PRECHECK 2.0: SOURCE REVIEWED OR STALE'; END IF;
  IF EXISTS (
    SELECT 1 FROM rkb2_ch2_claim_review c JOIN source_usage u ON u.usage_id=c.usage_id
    JOIN sources s ON s.source_id=u.source_id JOIN dissertation_sections d ON d.section_id=u.section_id
    WHERE d.section_code='2.0' AND s.citation_number BETWEEN 15 AND 18 AND
    (c.review_status NOT IN ('open','in_review') OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
     OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))
  ) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PRECHECK 2.0: CLAIM REVIEWED OR STALE'; END IF;

  START TRANSACTION;
  UPDATE rkb2_ch2_source_review AS r
  JOIN sources AS s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CONCAT('https://doi.org/',s.doi),
      r.edition_or_version=CASE s.citation_number
 WHEN 15 THEN 'Wiley-Volltext, 26(2), S.91-108; Abstract; Method; Results/Table 1'
 WHEN 16 THEN 'Elsevier ScienceDirect, Journal of Business Research 104 (2019), S.333-339; Abstract und Verlagstext'
 WHEN 17 THEN 'SAGE, Human Resource Development Review 4(3), S.356-367; nur offizieller Abstract frei verfügbar'
 WHEN 18 THEN 'BMJ 372:n71 (2021); PRISMA 2020 Statement, Abstract; 27-item checklist'
 ELSE NULL END,
      r.metadata_comparison=CASE s.citation_number
 WHEN 15 THEN 'Autorinnen/Autoren, Journal, Jahr 2009, Band 26, Heft 2, S. 91-108 und DOI anhand Verlagsseite geprüft; 14 Reviewtypen und SALSA in Abstract/Method/Results ausdrücklich genannt.'
 WHEN 16 THEN 'Titel, Hannah Snyder, Journal of Business Research Bd. 104, S.333-339 und DOI auf Verlagsseite bestätigt. Integrative, systematische und weitere Reviewansätze werden eingeordnet.'
 WHEN 17 THEN 'Titel, Richard J. Torraco, Heft 4(3), September 2005 und DOI auf SAGE-Seite nachweisbar. Volltext ist zugangsbeschränkt.'
 WHEN 18 THEN 'Page und Mitautoren, BMJ 2021;372:n71 sowie DOI anhand BMJ und PubMed geprüft. PRISMA 2020 ist eine Berichtsleitlinie für systematische Reviews.'
 ELSE NULL END
  WHERE s.citation_number BETWEEN 15 AND 18 AND r.review_status IN ('open','in_review');

  UPDATE rkb2_ch2_claim_review AS c
  JOIN source_usage AS u ON u.usage_id=c.usage_id
  JOIN sources AS s ON s.source_id=u.source_id
  JOIN dissertation_sections AS d ON d.section_id=u.section_id
  SET c.review_status='in_review',
      c.evidence_uri=CONCAT('https://doi.org/',s.doi),
      c.edition_or_version=CASE s.citation_number
 WHEN 15 THEN 'Wiley-Volltext, 26(2), S.91-108; Abstract; Method; Results/Table 1'
 WHEN 16 THEN 'Elsevier ScienceDirect, Journal of Business Research 104 (2019), S.333-339; Abstract und Verlagstext'
 WHEN 17 THEN 'SAGE, Human Resource Development Review 4(3), S.356-367; nur offizieller Abstract frei verfügbar'
 WHEN 18 THEN 'BMJ 372:n71 (2021); PRISMA 2020 Statement, Abstract; 27-item checklist'
 ELSE NULL END,
      c.page_or_section=CASE s.citation_number
 WHEN 15 THEN 'Abstract: Methods/Results; Artikel: Method und Results/Table 1'
 WHEN 16 THEN 'Abstract; Abschnitt zur Typologie der Literaturreviews (Detailabgleich noch offen)'
 WHEN 17 THEN 'Verlagsabstract; Original-Volltext und S.356-367 nicht vollständig prüfbar'
 WHEN 18 THEN 'Abstract; Einleitung und Abschnitt zur 27-Item-Checkliste'
 ELSE NULL END,
      c.assessment=CASE s.citation_number
 WHEN 15 THEN 'Datenbank-Claim: 14 Reviewtypen und methodischer SALSA-Vergleich. Auf der offiziellen Wiley-Seite direkt belegt. Fachlicher Schlussvergleich mit konkretem deutschen Manuskriptsatz und unabhängige Signatur noch offen.'
 WHEN 16 THEN 'Datenbank-Claim: Eignung und Transparenz integrativer und weiterer Reviews. Grundrichtung durch Original-Verlagsabstract und publizierte Methodeneinordnung gestützt; genaue Unterabschnitts- und Seitenzuordnung für alle Teilbehauptungen noch fachlich nachprüfen.'
 WHEN 17 THEN 'Datenbank-Claim: integrativer Review als eigenständige Erkenntnis-/Konzeptarbeit. Der eigenständige Erkenntnisbeitrag ist durch den SAGE-Abstract gestützt. Weitergehende Aussagen über Kritik, Synthese und Theorieentwicklung erst nach Originalstellenprüfung übernehmen; VORLÄUFIG.'
 WHEN 18 THEN 'Datenbank-Claim: PRISMA 2020 als Berichtsleitlinie, nicht Zertifizierung einer eigenen integrativen Literaturuntersuchung. Berichtsleitlinie direkt belegt; negative Abgrenzung zu FRZK ist eine sachgerechte methodische Interpretation, keine wörtliche PRISMA-Aussage.'
 ELSE NULL END
  WHERE d.section_code='2.0' AND s.citation_number BETWEEN 15 AND 18
    AND c.review_status IN ('open','in_review');

  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review AS r
  JOIN sources AS s ON s.source_id=r.source_id
  WHERE s.citation_number BETWEEN 15 AND 18 AND r.review_status='in_review'
    AND r.evidence_uri IS NOT NULL AND r.metadata_comparison IS NOT NULL
    AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review AS c
  JOIN source_usage AS u ON u.usage_id=c.usage_id
  JOIN dissertation_sections AS d ON d.section_id=u.section_id
  JOIN sources AS s ON s.source_id=u.source_id
  WHERE d.section_code='2.0' AND s.citation_number BETWEEN 15 AND 18
    AND c.review_status='in_review' AND c.evidence_uri IS NOT NULL
    AND c.assessment IS NOT NULL AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources<>4 OR v_claims<>4 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PRECHECK 2.0: POSTSTATE FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_20_EVIDENCE_PRESTAGED' AS check_code,'PASS' AS result,
         v_sources AS source_in_review,v_claims AS claims_in_review,
         'No scientific gates changed; no accepted/supported/verified flags set' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_21` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 REGISTERSIZE CHANGED';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u
       JOIN dissertation_sections d ON d.section_id=u.section_id
       JOIN sources s ON s.source_id=u.source_id
       JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
       JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
       WHERE d.section_code='2.1' AND s.citation_number BETWEEN 19 AND 31) <> 13 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 SOURCE OR CLAIM COUNT CHANGED';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l
       JOIN dissertation_sections d ON d.section_id=l.section_id
       WHERE d.section_code='2.1' AND l.object_type='manuscript'
       AND BINARY SHA2(l.new_value,256)=BINARY '16703a280cfef8b302770f11eaaf9c3723e343785861753911ad1254a346e143')<>1 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 IMPORT TEXT SHA FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
       WHERE s.citation_number BETWEEN 19 AND 31
       AND (r.review_status <> 'open' OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
         OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,
            COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 SOURCE REVIEW STALE OR ALREADY REVIEWED';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c
       JOIN source_usage u ON u.usage_id=c.usage_id
       JOIN dissertation_sections d ON d.section_id=u.section_id
       JOIN sources s ON s.source_id=u.source_id
       WHERE d.section_code='2.1' AND s.citation_number BETWEEN 19 AND 31
       AND (c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
         OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),
            COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 CLAIM REVIEW STALE OR ALREADY REVIEWED';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.0' AND review_status='in_review') <> 4 THEN
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.0 REVIEW STATE DIFFERENT';
  END IF;

  START TRANSACTION;
  UPDATE rkb2_ch2_source_review r
  JOIN sources s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CASE s.citation_number
 WHEN 19 THEN 'https://doi.org/10.1007/s10649-019-09903-9'
 WHEN 20 THEN 'https://link.springer.com/book/10.1007/978-3-319-45004-9'
 WHEN 21 THEN 'https://doi.org/10.1007/978-3-319-12688-3_9'
 WHEN 22 THEN 'https://doi.org/10.1533/9780857099419.5.221'
 WHEN 23 THEN 'https://doi.org/10.1007/BF02655883'
 WHEN 24 THEN 'https://doi.org/10.1007/BF02655885'
 WHEN 25 THEN 'https://doi.org/10.2307/4149958'
 WHEN 26 THEN 'https://doi.org/10.1007/BF02655886'
 WHEN 27 THEN 'https://www.routledge.com/Beyond-Constructivism-Models-and-Modeling-Perspectives-on-Mathematics-Problem-Solving-Learning-and-Teaching/Lesh-Doerr/p/book/9780805838220'
 WHEN 28 THEN 'https://doi.org/10.1093/oso/9780192895622.001.0001'
 WHEN 29 THEN 'https://doi.org/10.1109/IEEESTD.2019.8766229'
 WHEN 30 THEN 'https://doi.org/10.1145/103162.103163'
 WHEN 31 THEN 'https://doi.org/10.1007/978-3-031-41026-0'
 ELSE NULL END,
      r.edition_or_version=CASE s.citation_number
 WHEN 19 THEN 'Educational Studies in Mathematics 102(1), 9–28 (2019); Forschungsportal Aarhus; Abstract'
 WHEN 20 THEN 'Springer OA Monografie, ICME-13 Topical Surveys, 2016; Kapitel 1–42'
 WHEN 21 THEN 'Springer Proceedings ICME-12, S. 73–96 (2015), Open Access'
 WHEN 22 THEN 'ICTMA12 Kapitel 5.1 (2007), ScienceDirect, S. 222–231'
 WHEN 23 THEN 'ZDM 38(2), 86–95 (2006); Artikel-PDF/Abstract zugänglich'
 WHEN 24 THEN 'ZDM 38(2), 113–142 (2006); Abstract/Verlagsangaben'
 WHEN 25 THEN 'JRME 33(5), 352–378 (2002); JSTOR offizielles Inhaltsverzeichnis'
 WHEN 26 THEN 'ZDM 38(2), 143–162 (2006); FIS-Bildung Fachportal/Abstract'
 WHEN 27 THEN 'Originalherausgeberband 2003 Lawrence Erlbaum; aktuelle Routledge-Ausgabe'
 WHEN 28 THEN 'OUP, Real Analysis and Infinity, 31.03.2022'
 WHEN 29 THEN 'IEEE Std 754-2019; IEEE Xplore Standardbeschreibung'
 WHEN 30 THEN 'ACM Computing Surveys 23(1), 5–48 (1991); frei zugaengliche Oracle-Reproduktion'
 WHEN 31 THEN 'Springer, Linear Algebra Done Right, 4. Auflage 2024, Open Access'
 ELSE NULL END,
      r.metadata_comparison=CASE s.citation_number
 WHEN 19 THEN 'Niss/Hoeggaard und KOM: Rahmung mathematischer Kompetenzen, Ueberarbeitung der Begriffe. Begriffsrevision durch Verlags-/Universitaetsabstract gestuetzt; detailgenauer Originalstellenabgleich noch ausstehend.'
 WHEN 20 THEN 'Deutschsprachige Modellierungsforschung, Modellierungszyklen und divergierende Perspektiven nachvollziehbar. Buch-DOI und Kapitel-DOI (Suffix _1) auseinanderhalten; Einzelaussagen noch abstimmen.'
 WHEN 21 THEN 'Blum behandelt Wechselspiel reale Welt / Mathematik und qualitaetsvollen Modellierungsunterricht. Die konkrete Reihenfolge von Vereinfachen, Mathematisieren, Loesen und Validieren ist mit Textstellen nachzupruefen.'
 WHEN 22 THEN 'DISUM, Arbeit von Schuelern und Lehrkraeften an konkreter Modellierungsaufgabe im Originalabstract bestaetigt. DOI endet auf .221, Kapitelzaehlung 5.1, Seiten 222–231; bibliografisch getrennt pruefen.'
 WHEN 23 THEN 'Differenzierung theoretischer und empirischer Modellierungsphasen und schwierige empirische Zuordnung von Aktivitaeten durch Originalabstract gestuetzt; Seitenabgleich erforderlich.'
 WHEN 24 THEN 'Maaß erlaeutert Modellierungskompetenzen und empirische Lern-/Unterrichtsdaten. Genauer Beleg fuer einzelne Fehlerkategorien und Stufen noch anhand Volltext pruefen.'
 WHEN 25 THEN 'Studie zum kovariationalen Denken in dynamischen Situationen ist bibliografisch identifiziert. Detaillierte Aussage zu Studierenden, fuinf Handlungsebenen und empirischer Gruppe anhand Volltext pruefen.'
 WHEN 26 THEN 'Modellierungsblockaden an Uebergaengen und Altersgruppe 14–15 im Originalabstract bestaetigt. Detaillierte Kategorien und Schlussfolgerungen im Volltext abgleichen.'
 WHEN 27 THEN 'Models-and-Modeling, Modellentwicklungssequenzen und Ueberarbeitung von Modellen sind anhand Inhaltsuebersicht gestuetzt. Erscheinungsangaben/Seitensumme alt-neu editionsabhaengig; nicht final abzeichnen.'
 WHEN 28 THEN 'Sedaghat behandelt Analysis einschliesslich reelle Zahlen, Grenzwerte und Unendlichkeit. Kein Beleg fuer spezielle FRZK-Rechenregeln; nur allgemeiner mathematischer Vergleich.'
 WHEN 29 THEN 'IEEE-754-Gleitkommaarithmetik umfasst besondere numerische Werte; +0 und -0 durch Goldberg textlich verdeutlicht. Konkrete IEEE-Normklausel und Lizenzausgabe fuer endgültige Belegstelle pruefen.'
 WHEN 30 THEN 'Goldberg behandelt Darstellung +0/-0, Vorzeichenrechnung und Zusammenhang mit Unendlichkeit. Signierte Gleitkommanull ist NICHT dasselbe wie gerichteter mathematischer Grenzzustand des FRZK.'
 WHEN 31 THEN 'Grundlagen gewoehnlicher Vektorraeume und Nullvektor. Die Behauptung, dass aus dem Nullvektor keine ursprüngliche Orientierung rekonstruierbar ist, ist eine mathematische Folgerung, keine explizite neue physikalische Quelle.'
 ELSE NULL END
  WHERE s.citation_number BETWEEN 19 AND 31 AND r.review_status='open';
  IF ROW_COUNT() <> 13 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 SOURCES UPDATE COUNT FAIL'; END IF;
  UPDATE rkb2_ch2_claim_review c
  JOIN source_usage u ON u.usage_id=c.usage_id
  JOIN sources s ON s.source_id=u.source_id
  JOIN dissertation_sections d ON d.section_id=u.section_id
  SET c.review_status='in_review',
      c.evidence_uri=CASE s.citation_number
 WHEN 19 THEN 'https://doi.org/10.1007/s10649-019-09903-9'
 WHEN 20 THEN 'https://link.springer.com/book/10.1007/978-3-319-45004-9'
 WHEN 21 THEN 'https://doi.org/10.1007/978-3-319-12688-3_9'
 WHEN 22 THEN 'https://doi.org/10.1533/9780857099419.5.221'
 WHEN 23 THEN 'https://doi.org/10.1007/BF02655883'
 WHEN 24 THEN 'https://doi.org/10.1007/BF02655885'
 WHEN 25 THEN 'https://doi.org/10.2307/4149958'
 WHEN 26 THEN 'https://doi.org/10.1007/BF02655886'
 WHEN 27 THEN 'https://www.routledge.com/Beyond-Constructivism-Models-and-Modeling-Perspectives-on-Mathematics-Problem-Solving-Learning-and-Teaching/Lesh-Doerr/p/book/9780805838220'
 WHEN 28 THEN 'https://doi.org/10.1093/oso/9780192895622.001.0001'
 WHEN 29 THEN 'https://doi.org/10.1109/IEEESTD.2019.8766229'
 WHEN 30 THEN 'https://doi.org/10.1145/103162.103163'
 WHEN 31 THEN 'https://doi.org/10.1007/978-3-031-41026-0'
 ELSE NULL END,
      c.edition_or_version=CASE s.citation_number
 WHEN 19 THEN 'Educational Studies in Mathematics 102(1), 9–28 (2019); Forschungsportal Aarhus; Abstract'
 WHEN 20 THEN 'Springer OA Monografie, ICME-13 Topical Surveys, 2016; Kapitel 1–42'
 WHEN 21 THEN 'Springer Proceedings ICME-12, S. 73–96 (2015), Open Access'
 WHEN 22 THEN 'ICTMA12 Kapitel 5.1 (2007), ScienceDirect, S. 222–231'
 WHEN 23 THEN 'ZDM 38(2), 86–95 (2006); Artikel-PDF/Abstract zugänglich'
 WHEN 24 THEN 'ZDM 38(2), 113–142 (2006); Abstract/Verlagsangaben'
 WHEN 25 THEN 'JRME 33(5), 352–378 (2002); JSTOR offizielles Inhaltsverzeichnis'
 WHEN 26 THEN 'ZDM 38(2), 143–162 (2006); FIS-Bildung Fachportal/Abstract'
 WHEN 27 THEN 'Originalherausgeberband 2003 Lawrence Erlbaum; aktuelle Routledge-Ausgabe'
 WHEN 28 THEN 'OUP, Real Analysis and Infinity, 31.03.2022'
 WHEN 29 THEN 'IEEE Std 754-2019; IEEE Xplore Standardbeschreibung'
 WHEN 30 THEN 'ACM Computing Surveys 23(1), 5–48 (1991); frei zugaengliche Oracle-Reproduktion'
 WHEN 31 THEN 'Springer, Linear Algebra Done Right, 4. Auflage 2024, Open Access'
 ELSE NULL END,
      c.page_or_section=CASE s.citation_number
 WHEN 19 THEN 'Universitaets-Forschungsportal: bibliografische Daten und Abstract'
 WHEN 20 THEN 'Springer: Buchoverview und OA-Kapitel, Inhaltsabschnitte zu Modellierungszyklen'
 WHEN 21 THEN 'Springer: Abstract, Kapitel/Abschnitte Modellierung, Anwendungen und Unterricht'
 WHEN 22 THEN 'ScienceDirect: offizieller Abstract, Beschreibung DISUM/Sugarloaf und Abschnittsfolge'
 WHEN 23 THEN 'Originalabstract: kognitionspsychologische Modellierungszyklen und COM2'
 WHEN 24 THEN 'Originalabstract: Definitionen von Modellierungskompetenzen und empirische Studie'
 WHEN 25 THEN 'JSTOR: Titel, fuenf Autoren und Seiten; Framework laut Publikation'
 WHEN 26 THEN 'Fachportal: abstract zu blockierten Uebergaengen bei 14–15-Jaehrigen'
 WHEN 27 THEN 'Verlag: Buchbeschreibung, Inhaltsverzeichnis, Herausgeber Lesh und Doerr'
 WHEN 28 THEN 'Oxford Academic: Beschreibung zu reellen Zahlen, Folgen, Grenzwerten, Unendlichkeit'
 WHEN 29 THEN 'IEEE: standardisierte binaere/dezimale Formate, Operationen und Ausnahmen'
 WHEN 30 THEN 'ACM-Metadaten, Oracle autorisierte Wiederveroeffentlichung: Abschnitt Signed Zero'
 WHEN 31 THEN 'Springer Lehrbuch und Autorenverzeichnis: Vektorräume, Nullvektor, Skalarmultiplikation'
 ELSE NULL END,
      c.assessment=CASE s.citation_number
 WHEN 19 THEN 'Niss/Hoeggaard und KOM: Rahmung mathematischer Kompetenzen, Ueberarbeitung der Begriffe. Begriffsrevision durch Verlags-/Universitaetsabstract gestuetzt; detailgenauer Originalstellenabgleich noch ausstehend.'
 WHEN 20 THEN 'Deutschsprachige Modellierungsforschung, Modellierungszyklen und divergierende Perspektiven nachvollziehbar. Buch-DOI und Kapitel-DOI (Suffix _1) auseinanderhalten; Einzelaussagen noch abstimmen.'
 WHEN 21 THEN 'Blum behandelt Wechselspiel reale Welt / Mathematik und qualitaetsvollen Modellierungsunterricht. Die konkrete Reihenfolge von Vereinfachen, Mathematisieren, Loesen und Validieren ist mit Textstellen nachzupruefen.'
 WHEN 22 THEN 'DISUM, Arbeit von Schuelern und Lehrkraeften an konkreter Modellierungsaufgabe im Originalabstract bestaetigt. DOI endet auf .221, Kapitelzaehlung 5.1, Seiten 222–231; bibliografisch getrennt pruefen.'
 WHEN 23 THEN 'Differenzierung theoretischer und empirischer Modellierungsphasen und schwierige empirische Zuordnung von Aktivitaeten durch Originalabstract gestuetzt; Seitenabgleich erforderlich.'
 WHEN 24 THEN 'Maaß erlaeutert Modellierungskompetenzen und empirische Lern-/Unterrichtsdaten. Genauer Beleg fuer einzelne Fehlerkategorien und Stufen noch anhand Volltext pruefen.'
 WHEN 25 THEN 'Studie zum kovariationalen Denken in dynamischen Situationen ist bibliografisch identifiziert. Detaillierte Aussage zu Studierenden, fuinf Handlungsebenen und empirischer Gruppe anhand Volltext pruefen.'
 WHEN 26 THEN 'Modellierungsblockaden an Uebergaengen und Altersgruppe 14–15 im Originalabstract bestaetigt. Detaillierte Kategorien und Schlussfolgerungen im Volltext abgleichen.'
 WHEN 27 THEN 'Models-and-Modeling, Modellentwicklungssequenzen und Ueberarbeitung von Modellen sind anhand Inhaltsuebersicht gestuetzt. Erscheinungsangaben/Seitensumme alt-neu editionsabhaengig; nicht final abzeichnen.'
 WHEN 28 THEN 'Sedaghat behandelt Analysis einschliesslich reelle Zahlen, Grenzwerte und Unendlichkeit. Kein Beleg fuer spezielle FRZK-Rechenregeln; nur allgemeiner mathematischer Vergleich.'
 WHEN 29 THEN 'IEEE-754-Gleitkommaarithmetik umfasst besondere numerische Werte; +0 und -0 durch Goldberg textlich verdeutlicht. Konkrete IEEE-Normklausel und Lizenzausgabe fuer endgültige Belegstelle pruefen.'
 WHEN 30 THEN 'Goldberg behandelt Darstellung +0/-0, Vorzeichenrechnung und Zusammenhang mit Unendlichkeit. Signierte Gleitkommanull ist NICHT dasselbe wie gerichteter mathematischer Grenzzustand des FRZK.'
 WHEN 31 THEN 'Grundlagen gewoehnlicher Vektorraeume und Nullvektor. Die Behauptung, dass aus dem Nullvektor keine ursprüngliche Orientierung rekonstruierbar ist, ist eine mathematische Folgerung, keine explizite neue physikalische Quelle.'
 ELSE NULL END
  WHERE d.section_code='2.1' AND s.citation_number BETWEEN 19 AND 31 AND c.review_status='open';
  IF ROW_COUNT() <> 13 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 CLAIMS UPDATE COUNT FAIL'; END IF;
  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
  WHERE s.citation_number BETWEEN 19 AND 31 AND r.review_status='in_review'
    AND r.evidence_uri IS NOT NULL AND r.metadata_comparison IS NOT NULL
    AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review c
    JOIN source_usage u ON u.usage_id=c.usage_id
    JOIN dissertation_sections d ON d.section_id=u.section_id
    JOIN sources s ON s.source_id=u.source_id
    WHERE d.section_code='2.1' AND s.citation_number BETWEEN 19 AND 31
    AND c.review_status='in_review' AND c.assessment IS NOT NULL
    AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources <> 13 OR v_claims <> 13 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.1 IN_REVIEW POSTSTATE FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_21_EVIDENCE_PRESTAGED' AS check_code, 'PASS' AS result,
         v_sources AS sources_in_review,v_claims AS claims_in_review,
         'Technical register update only. Claims/metadata/science gates remain OPEN.' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_210` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review)=141) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CLAIM_REGISTER_141 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review)=135) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SOURCE_REGISTER_135 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND status='draft')=12) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CHAPTER2_12_DRAFT FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND status IN ('final','released'))=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CH2_NOT_RELEASED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 15 AND 149 AND verification_status='verified')=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SOURCE_VERIFIED_0 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND u.citation_checked=1)=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE MAIN_CITATIONS_CHECKED_ZERO FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review WHERE review_status='in_review')=127) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SOURCE_IN_REVIEW_127 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review WHERE review_status='open')=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SOURCE_OPEN_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='in_review')=133) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CLAIM_IN_REVIEW_133 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='open')=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CLAIM_OPEN_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='supported')=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CLAIM_SUPPORTED_ZERO FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status IN ('needs_revision','rejected'))=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CLAIM_CRITICAL_ZERO FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review WHERE review_status='accepted')=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SOURCE_ACCEPTED_ZERO FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review WHERE review_status IN ('needs_revision','rejected'))=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SOURCE_CRITICAL_ZERO FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 142 AND 149)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE CITATION_IDS_142_149_EXACTLY_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id WHERE d.section_code='2.10' AND u.citation_checked=0)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE MAIN_CITATIONS_210_UNCHECKED_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id WHERE d.section_code='2.10')=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE EXACT_8_TARGET_USAGE FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id JOIN sources s ON s.source_id=u.source_id WHERE d.section_code='2.10' AND s.citation_number BETWEEN 142 AND 149)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE EXACT_8_TARGET_SOURCES FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 142 AND 149 AND verification_status='partially_verified')=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE EXACT_8_PARTIALLY_VERIFIED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM section_change_log l JOIN dissertation_sections d ON d.section_id=l.section_id WHERE d.section_code='2.10' AND l.object_type='manuscript' AND BINARY SHA2(l.new_value,256)=BINARY '02c7dbaaceb1f9b1134d26854d35fc241c2f7a64360898b5699560b40577ddeb')=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SEC210_HASH_UNCHANGED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM section_change_log l JOIN dissertation_sections d ON d.section_id=l.section_id WHERE l.object_type='manuscript' AND ((d.section_code='2.0' AND BINARY SHA2(l.new_value,256)=BINARY 'd16e8ffeff24c45d405f536c1e7921abf894aa4808e6516772cf47b4a8b6768b') OR (d.section_code='2.1' AND BINARY SHA2(l.new_value,256)=BINARY '16703a280cfef8b302770f11eaaf9c3723e343785861753911ad1254a346e143') OR (d.section_code='2.2' AND BINARY SHA2(l.new_value,256)=BINARY '80970d0719b7a780eda5a8d771f4561bda30cb6d359a96b2fbcbf92c31315059') OR (d.section_code='2.3' AND BINARY SHA2(l.new_value,256)=BINARY '0e1b807d6b0d4ffc133c80dd482a1fc143c9b2b39becec5598ce0a66fa15823e') OR (d.section_code='2.4' AND BINARY SHA2(l.new_value,256)=BINARY 'b4f9c21d9de2c7c3bbcc3177bf378ae7470763c1d056cd99b64a9a2355217f8c') OR (d.section_code='2.5' AND BINARY SHA2(l.new_value,256)=BINARY 'c38f6ff1362035926324b94374337e44336d0dc36c806c02f88a79b73ba6a314') OR (d.section_code='2.6' AND BINARY SHA2(l.new_value,256)=BINARY '97b50e210b72ecd90d4959282e9ca5d3e11c7d54ef4b9fa1acaa019a63eba735') OR (d.section_code='2.7' AND BINARY SHA2(l.new_value,256)=BINARY 'cabf32528857bbb4648529ec95ab6623490ad158cc1ae2176912606e6f82fcd0') OR (d.section_code='2.8' AND BINARY SHA2(l.new_value,256)=BINARY '3b5c4b4b55f48ddf79ea70e8a7edd8b111c30415903478fc81d4962a7bff8817') OR (d.section_code='2.9' AND BINARY SHA2(l.new_value,256)=BINARY '74ba34df4f9afc3b3b8baadd926dbf3366dbb9ffbd9e93d7546cb85a875e0364')))=10) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE ALL_PREVIOUS_10_TEXT_HASHES FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id WHERE s.citation_number BETWEEN 142 AND 149 AND BINARY r.source_fingerprint=BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_SOURCE_FINGERPRINT_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review c JOIN source_usage u ON u.usage_id=c.usage_id JOIN dissertation_sections d ON d.section_id=u.section_id WHERE d.section_code='2.10' AND BINARY c.claim_fingerprint=BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_CLAIM_FINGERPRINT_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.10' AND reviewer IS NULL AND reviewed_at IS NULL)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_CLAIM_REVIEWERS_NULL FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id WHERE s.citation_number BETWEEN 142 AND 149 AND r.reviewer IS NULL AND r.reviewed_at IS NULL)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_SOURCE_REVIEWERS_NULL FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.0' AND review_status='in_review')=4) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_0_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.1' AND review_status='in_review')=13) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_1_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.2' AND review_status='in_review')=10) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_2_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.3' AND review_status='in_review')=14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_3_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.4' AND review_status='in_review')=14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_4_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.5' AND review_status='in_review')=16) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_5_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.6' AND review_status='in_review')=17) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_6_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.7' AND review_status='in_review')=17) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_7_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.8' AND review_status='in_review')=15) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_8_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.9' AND review_status='in_review')=13) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE SECTION_2_9_REVIEW_PRESERVED FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id WHERE s.citation_number BETWEEN 15 AND 141 AND r.review_status='in_review')=127) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE PRIOR_SOURCES_STILL_IN_REVIEW_127 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code<>'2.10' AND review_status='in_review')=133) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE PRIOR_CLAIMS_IN_REVIEW_133 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id WHERE s.citation_number BETWEEN 15 AND 141 AND BINARY r.source_fingerprint=BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))=127) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE PRIOR_SOURCE_FINGERPRINTS_127 FAIL'; END IF;
