  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.10' AND review_status='open')=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_CLAIMS_STILL_OPEN_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id WHERE s.citation_number BETWEEN 142 AND 149 AND r.evidence_uri IS NULL AND r.edition_or_version IS NULL AND r.metadata_comparison IS NULL)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_SOURCES_NO_EVIDENCE_8 FAIL'; END IF;
  IF NOT ((SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.10' AND evidence_uri IS NULL AND edition_or_version IS NULL AND page_or_section IS NULL AND assessment IS NULL)=8) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 PRESTATE TARGET_CLAIMS_NO_EVIDENCE_8 FAIL'; END IF;
  -- Quellennachweise: nur die acht bislang OPEN markierten Quellen.
  UPDATE rkb2_ch2_source_review AS r
  JOIN sources AS s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CASE s.citation_number
    WHEN 142 THEN 'https://www.sciencedirect.com/book/9780122384400/elements-of-set-theory'
    WHEN 143 THEN 'https://link.springer.com/book/10.1007/978-1-4612-6387-6'
    WHEN 144 THEN 'https://books.google.com/books?id=S6QYeuo4p1EC'
    WHEN 145 THEN 'https://link.springer.com/book/10.1007/978-1-4757-4721-8'
    WHEN 146 THEN 'https://doi.org/10.1016/j.entcs.2018.10.009'
    WHEN 147 THEN 'https://lamport.azurewebsites.net/tla/book.html'
    WHEN 148 THEN 'https://eric.ed.gov/?id=EJ639864'
    WHEN 149 THEN 'https://link.springer.com/book/9783642481376'
    ELSE NULL END,
      r.edition_or_version=CASE s.citation_number
    WHEN 142 THEN 'Academic Press, 1977, ISBN 9780122384400, Verlag ScienceDirect; DOI 10.1016/C2009-0-22079-4'
    WHEN 143 THEN 'Halmos 1958, 2. Aufl., Originaldruck Van Nostrand; separater Springer-Online-Nachweis mit DOI 10.1007/978-1-4612-6387-6'
    WHEN 144 THEN 'Cambridge University Press, 1997, A Shorter Model Theory, 310 S.; Verlags-/Google-Books-Auszug'
    WHEN 145 THEN 'Springer New York, 2. Aufl. (Hardcover 1998), GTM 5; E-Book DOI 10.1007/978-1-4757-4721-8 (2013)'
    WHEN 146 THEN 'Electronic Notes in Theoretical Computer Science 338 (2018), S.133–145, Elsevier, Open Access, DOI 10.1016/j.entcs.2018.10.009'
    WHEN 147 THEN 'Leslie Lamport, Specifying Systems: The TLA+ Language and Tools for Hardware and Software Engineers, Addison-Wesley, Copyright 2002'
    WHEN 148 THEN 'Educational Studies in Mathematics 44(1–2) (2000), S.5–23; DOI 10.1023/A:1012737223465'
    WHEN 149 THEN 'Springer-Verlag Berlin/Heidelberg, Original-Copyright 1967; neu aufgelegte Springer-Verlagsseite 2012'
    ELSE NULL END,
      r.metadata_comparison=CASE s.citation_number
    WHEN 142 THEN 'Academic Press 1977, DOI und ISBN vom Verlag bestaetigt. WorldCat kann abweichenden Ortsnamen nennen; genaue Druckortangabe fuer FINAL pruefen.'
    WHEN 143 THEN 'Springer weist ©1958 aus, der DOI bezeichnet elektronische Springer-Ausgabe; NICHT als DOI der Van-Nostrand-Druckausgabe von 1958 ausgeben. Verlagsort der Printausgabe noch ueber Titelblatt klaeren.'
    WHEN 144 THEN 'Autor, Titel, Verlag und Jahr identifiziert; Kapitel/Seiten aus Inhaltsverzeichnis, noch nicht Volltext-Claim-bezogen abgeglichen.'
    WHEN 145 THEN 'Springer nennt ©1978, Hardcover 1998, 2. Auflage und digitales DOI von 2013: die Editions- und Publikationsjahre in der Endbibliografie differenzieren.'
    WHEN 146 THEN 'Elsevier DOI, Jahr, Autoren, Zeitschrift und Seiten 133–145 bestaetigt. Uebertragbarkeit auf FRZK nicht behaupten.'
    WHEN 147 THEN 'Autor bietet Originalbuch und Korrekturen selbst an; neuere Sprachversion unterscheidet sich vom Buch (2002). Ausgabe und Werkzeuge nicht gleichsetzen.'
    WHEN 148 THEN 'ERIC belegt Titel, Autor, Zeitschriftenband 44, Heft 1–2, Jahr und Seiten 5–23; Text nach Abstract, noch keine Abzeichnung einzelner Textstellen.'
    WHEN 149 THEN 'Springer ©1967, Springer-Softcover 2012. Achtung: aehnliche Titel Scientific Research: The Search for System koennen Band/Teil anders zaehlen; konkrete Originalausgabe nach Titelblatt pruefen.'
    ELSE NULL END
  WHERE s.citation_number BETWEEN 142 AND 149
    AND r.review_status='open' AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  IF ROW_COUNT() <> 8 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 SOURCE UPDATE COUNT FAIL';
  END IF;

  -- Claim-Nachweise: explizite Verknuepfung mit Abschnitt 2.10.
  UPDATE rkb2_ch2_claim_review AS c
  JOIN source_usage AS u ON u.usage_id=c.usage_id
  JOIN dissertation_sections AS d ON d.section_id=u.section_id
  JOIN sources AS s ON s.source_id=u.source_id
  SET c.review_status='in_review',
      c.evidence_uri=CASE s.citation_number
    WHEN 142 THEN 'https://www.sciencedirect.com/book/9780122384400/elements-of-set-theory'
    WHEN 143 THEN 'https://link.springer.com/book/10.1007/978-1-4612-6387-6'
    WHEN 144 THEN 'https://books.google.com/books?id=S6QYeuo4p1EC'
    WHEN 145 THEN 'https://link.springer.com/book/10.1007/978-1-4757-4721-8'
    WHEN 146 THEN 'https://doi.org/10.1016/j.entcs.2018.10.009'
    WHEN 147 THEN 'https://lamport.azurewebsites.net/tla/book.html'
    WHEN 148 THEN 'https://eric.ed.gov/?id=EJ639864'
    WHEN 149 THEN 'https://link.springer.com/book/9783642481376'
    ELSE NULL END,
      c.edition_or_version=CASE s.citation_number
    WHEN 142 THEN 'Academic Press, 1977, ISBN 9780122384400, Verlag ScienceDirect; DOI 10.1016/C2009-0-22079-4'
    WHEN 143 THEN 'Halmos 1958, 2. Aufl., Originaldruck Van Nostrand; separater Springer-Online-Nachweis mit DOI 10.1007/978-1-4612-6387-6'
    WHEN 144 THEN 'Cambridge University Press, 1997, A Shorter Model Theory, 310 S.; Verlags-/Google-Books-Auszug'
    WHEN 145 THEN 'Springer New York, 2. Aufl. (Hardcover 1998), GTM 5; E-Book DOI 10.1007/978-1-4757-4721-8 (2013)'
    WHEN 146 THEN 'Electronic Notes in Theoretical Computer Science 338 (2018), S.133–145, Elsevier, Open Access, DOI 10.1016/j.entcs.2018.10.009'
    WHEN 147 THEN 'Leslie Lamport, Specifying Systems: The TLA+ Language and Tools for Hardware and Software Engineers, Addison-Wesley, Copyright 2002'
    WHEN 148 THEN 'Educational Studies in Mathematics 44(1–2) (2000), S.5–23; DOI 10.1023/A:1012737223465'
    WHEN 149 THEN 'Springer-Verlag Berlin/Heidelberg, Original-Copyright 1967; neu aufgelegte Springer-Verlagsseite 2012'
    ELSE NULL END,
      c.page_or_section=CASE s.citation_number
    WHEN 142 THEN 'Verlagsbeschreibung (Overview / Details); formale Objekte, Mengen, Relationen und Funktionen; konkrete Def.-Seiten noch offen'
    WHEN 143 THEN 'Springer Buchbeschreibung; Google Books Inhaltsverzeichnis: Vector Spaces / Orthogonality; konkrete Nullvektorstelle noch offen'
    WHEN 144 THEN 'Inhaltsverzeichnis: Interpretations S.93, Interpreting one structure in another S.107, Expanding the language S.147'
    WHEN 145 THEN 'Springer Inhaltsverzeichnis: Categories, Functors, and Natural Transformations S.7–30, Constructions S.31–53'
    WHEN 146 THEN 'Originalartikel: Abstract; Abschnitt 2 (Definitional Theories), Abschnitt 3 (Modelltheoretische Konservativitaet)'
    WHEN 147 THEN 'Autorenwebsite: Inhaltsverzeichnis, Kapitel 7 Writing a Specification und Kapitel 14 TLC Model Checker'
    WHEN 148 THEN 'ERIC Abstract: Bedeutung von Beweis, Heuristik, Exploration und Visualisierung; genaue Originalseiten offen'
    WHEN 149 THEN 'Verlagsuebersicht Scientific Research I, systematische wissenschaftliche Forschung; spezielle Methodenaussage mit Printseiten abzugleichen'
    ELSE NULL END,
      c.assessment=CASE s.citation_number
    WHEN 142 THEN 'Verlag bestaetigt bibliografische Angaben und die Einfuehrung in Mengenlehre. Keine Originalseitenpruefung fuer die konkrete FRZK-Definition. Gerichtet-symbolische Nullwerte werden dort nicht belegt.'
    WHEN 143 THEN 'Grundlagen von Vektorraeumen und Orthogonalitaet sind thematisch gesichert. Die Nichtrueckgewinnbarkeit einer frueheren Orientierung aus 0·v ist eine eigene mathematische Schlussfolgerung, keine explizite Sondertheorie von Halmos.'
    WHEN 144 THEN 'Modelltheoretische Interpretation und Strukturbeziehungen sind im Inhalt nachgewiesen. Ein FRZK-Modell ist damit noch nicht interpretiert und die Axiome sind nicht automatisch konsistent.'
    WHEN 145 THEN 'Funktoren, Kategorien und strukturwahrende Zusammenhaenge sind im Buch dargestellt. FRZK muss nicht kategorientheoretisch sein; diese Quelle liefert keine unmittelbare formale Validierung eigener Rechenregeln.'
    WHEN 146 THEN 'Originalabstract belegt Konservativitaet unter besonderen formalen Voraussetzungen. Gilt fuer dort definierte Theorien; nicht ohne FRZK-Modell und Beweis auf dieses uebertragbar.'
    WHEN 147 THEN 'Trennung von Spezifikationen und Werkzeugpruefung ist im Originalbuch beschrieben. TLA+/TLC ist keine allgemeine Beweisinstanz fuer eigene FRZK-Strukturen; formale mathematische Beweise bleiben gesondert.'
    WHEN 148 THEN 'Der Beitrag diskutiert die Funktionen von Beweis und Erklaerung im Unterricht. Das FRZK profitiert allenfalls methodisch von dieser Unterscheidung; kein FRZK-spezifischer Wirksamkeitsnachweis.'
    WHEN 149 THEN 'Wissenschaftssystematische Perspektive und Werkidentitaet gesichert. Trennung von mathematischen, didaktischen und empirischen Anspruechen ist die methodische Schlussfolgerung der Dissertation, nicht das Ergebnis einer FRZK-Studie bei Bunge.'
    ELSE NULL END
  WHERE d.section_code='2.10' AND s.citation_number BETWEEN 142 AND 149
    AND c.review_status='open' AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF ROW_COUNT() <> 8 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 CLAIM UPDATE COUNT FAIL';
  END IF;

  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review r
    JOIN sources s ON s.source_id=r.source_id
    WHERE s.citation_number BETWEEN 142 AND 149 AND r.review_status='in_review'
      AND r.evidence_uri IS NOT NULL AND r.edition_or_version IS NOT NULL
      AND r.metadata_comparison IS NOT NULL AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review c
    WHERE c.section_code='2.10' AND c.review_status='in_review'
      AND c.evidence_uri IS NOT NULL AND c.edition_or_version IS NOT NULL
      AND c.page_or_section IS NOT NULL AND c.assessment IS NOT NULL
      AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources<>8 OR v_claims<>8 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.10 EVIDENCE POSTSTATE FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_210_EVIDENCE_PRESTAGED' AS check_code, 'PASS' AS result,
         v_sources AS sources_in_review, v_claims AS claims_in_review,
         'ONLY evidence register updated. Gate 05 remains BLOCKED.' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_22` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 AUDIT REGISTER COUNT DIFFERS';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u
       JOIN dissertation_sections d ON d.section_id=u.section_id
       JOIN sources s ON s.source_id=u.source_id
       JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
       JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
       WHERE d.section_code='2.2' AND s.citation_number BETWEEN 32 AND 41) <> 10 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 SOURCE-USAGE INTEGRITY FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l
       JOIN dissertation_sections d ON d.section_id=l.section_id
       WHERE d.section_code='2.2' AND l.object_type='manuscript'
       AND BINARY SHA2(l.new_value,256)=BINARY '80970d0719b7a780eda5a8d771f4561bda30cb6d359a96b2fbcbf92c31315059') <> 1 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 IMPORT TEXT SHA FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r
       JOIN sources s ON s.source_id=r.source_id
       WHERE s.citation_number BETWEEN 32 AND 41 AND (
         r.review_status <> 'open' OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
         OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,
                COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 SOURCE REVIEW STALE OR NOT OPEN';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c
       JOIN source_usage u ON u.usage_id=c.usage_id
       JOIN dissertation_sections d ON d.section_id=u.section_id
       JOIN sources s ON s.source_id=u.source_id
       WHERE d.section_code='2.2' AND s.citation_number BETWEEN 32 AND 41 AND (
         c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
         OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),
                COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 CLAIM REVIEW STALE OR NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.0' AND review_status='in_review') <> 4 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.1' AND review_status='in_review') <> 13 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 PRIOR PRECHECKS NOT COMPLETE';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.2' AND review_status='open') <> 10 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 CLAIM STATE NOT INITIAL';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
      WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND u.citation_checked=1) <> 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MAIN CITATION FLAGS CHANGED';
  END IF;

  START TRANSACTION;
  UPDATE rkb2_ch2_source_review r
  JOIN sources s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CASE s.citation_number
        WHEN 32 THEN 'https://doi.org/10.1007/s10649-006-0400-z'
        WHEN 33 THEN 'https://doi.org/10.1111/j.1551-6708.1987.tb00863.x'
        WHEN 34 THEN 'https://doi.org/10.1023/A:1024312321077'
        WHEN 35 THEN 'https://doi.org/10.1016/j.learninstruc.2006.03.001'
        WHEN 36 THEN 'https://doi.org/10.1016/S0959-4752(02)00017-8'
        WHEN 37 THEN 'https://doi.org/10.1007/s10648-016-9365-3'
        WHEN 38 THEN 'https://cmap.ihmc.us/docs/theory-of-concept-maps.php'
        WHEN 39 THEN 'https://doi.org/10.3102/00346543076003413'
        WHEN 40 THEN 'https://doi.org/10.1023/A:1013132527007'
        WHEN 41 THEN 'https://doi.org/10.1126/science.1204153'
        ELSE NULL END,
      r.edition_or_version=CASE s.citation_number
        WHEN 32 THEN 'Springer, Educational Studies in Mathematics 61, 103–131 (2006); DOI/Abstract'
        WHEN 33 THEN 'Wiley, Cognitive Science 11(1), 65–100 (1987); paralleler Elsevier-PII/DOI vorhanden'
        WHEN 34 THEN 'Springer, Educational Studies in Mathematics 52, 215–241 (2003)'
        WHEN 35 THEN 'Elsevier, Learning and Instruction 16(3), 183–198 (2006); Universitaet Nottingham'
        WHEN 36 THEN 'ScienceDirect, Learning and Instruction 13(2), 141–156 (2003)'
        WHEN 37 THEN 'Springer, Educational Psychology Review 29(4), 717–761 (Druck 2017; online 2016)'
        WHEN 38 THEN 'IHMC CmapTools Technical Report 2006-01 Rev 01-2008; Original-Eigenpublikation'
        WHEN 39 THEN 'SAGE, Review of Educational Research 76(3), 413–448 (2006)'
        WHEN 40 THEN 'Springer, Educational Psychology Review 14(1), 71–86 (2002)'
        WHEN 41 THEN 'Science 333(6046), 1096–1097 (2011); PubMed und Nottingham-Autorenrepository'
        ELSE NULL END,
      r.metadata_comparison=CASE s.citation_number
        WHEN 32 THEN 'Titel, Autor, Erscheinungsjahr, Band, Seiten, DOI beim Verlag bestaetigt. Nur Abstract und Verlagsmetadaten als direkt belegte Fundstelle.'
        WHEN 33 THEN 'Wiley-DOI der historischen Zeitschriftenausgabe bestaetigt; Elsevier fuehrt denselben Artikel auch unter 10.1016/S0364-0213(87)80026-5; keine zweite Literaturquelle anlegen.'
        WHEN 34 THEN 'Autor Arcavi; Band 52, Seiten 215–241, Jahr 2003, DOI beim Verlag bestaetigt.'
        WHEN 35 THEN 'Titel, Autorin, Zeitschrift, Band/Heft, Seiten, DOI ueber Universitaetsrepository bestaetigt; Volltextabschnitt zu Funktionsklassen fuer finalen Claim-Abgleich offen.'
        WHEN 36 THEN 'Autoren Schnotz und Bannert, Titel im Original im Singular representation, Seiten 141–156 und DOI bei Elsevier bestaetigt.'
        WHEN 37 THEN 'Autorin Rau, Druckjahr 2017, Band/Heft und Seiten in ERIC/Original-PDF verifiziert; Online-first 2016 separat vermerkt.'
        WHEN 38 THEN 'Autoren Novak und Cañas, Technikreportnummer und Revision 01-2008 durch IHMC-Fussnote bestaetigt. Der Titel des Reportes ist nicht mit kuerzerem 2006-Webtitel zu verwechseln.'
        WHEN 39 THEN 'Nesbit/Adesope, Jahrgang/Heft/Seiten und DOI durch SAGE/ERIC bestaetigt.'
        WHEN 40 THEN 'Autoren O''Donnell, Dansereau, Hall; Jahr 2002, Band/Heft/Seiten und DOI anhand Universitaetsrepository bestaetigt.'
        WHEN 41 THEN 'Ainsworth, Prain, Tytler, Jahr 2011, 333(6046), 1096–1097 und DOI durch PubMed/Nottingham bestaetigt.'
        ELSE NULL END
  WHERE s.citation_number BETWEEN 32 AND 41 AND r.review_status='open';
  IF ROW_COUNT() <> 10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 SOURCES UPDATE COUNT FAIL'; END IF;
  UPDATE rkb2_ch2_claim_review c
  JOIN source_usage u ON u.usage_id=c.usage_id
  JOIN sources s ON s.source_id=u.source_id
  JOIN dissertation_sections d ON d.section_id=u.section_id
  SET c.review_status='in_review',
      c.evidence_uri=CASE s.citation_number
        WHEN 32 THEN 'https://doi.org/10.1007/s10649-006-0400-z'
        WHEN 33 THEN 'https://doi.org/10.1111/j.1551-6708.1987.tb00863.x'
        WHEN 34 THEN 'https://doi.org/10.1023/A:1024312321077'
        WHEN 35 THEN 'https://doi.org/10.1016/j.learninstruc.2006.03.001'
        WHEN 36 THEN 'https://doi.org/10.1016/S0959-4752(02)00017-8'
        WHEN 37 THEN 'https://doi.org/10.1007/s10648-016-9365-3'
        WHEN 38 THEN 'https://cmap.ihmc.us/docs/theory-of-concept-maps.php'
        WHEN 39 THEN 'https://doi.org/10.3102/00346543076003413'
        WHEN 40 THEN 'https://doi.org/10.1023/A:1013132527007'
        WHEN 41 THEN 'https://doi.org/10.1126/science.1204153'
        ELSE NULL END,
      c.edition_or_version=CASE s.citation_number
        WHEN 32 THEN 'Springer, Educational Studies in Mathematics 61, 103–131 (2006); DOI/Abstract'
        WHEN 33 THEN 'Wiley, Cognitive Science 11(1), 65–100 (1987); paralleler Elsevier-PII/DOI vorhanden'
        WHEN 34 THEN 'Springer, Educational Studies in Mathematics 52, 215–241 (2003)'
        WHEN 35 THEN 'Elsevier, Learning and Instruction 16(3), 183–198 (2006); Universitaet Nottingham'
        WHEN 36 THEN 'ScienceDirect, Learning and Instruction 13(2), 141–156 (2003)'
        WHEN 37 THEN 'Springer, Educational Psychology Review 29(4), 717–761 (Druck 2017; online 2016)'
        WHEN 38 THEN 'IHMC CmapTools Technical Report 2006-01 Rev 01-2008; Original-Eigenpublikation'
        WHEN 39 THEN 'SAGE, Review of Educational Research 76(3), 413–448 (2006)'
        WHEN 40 THEN 'Springer, Educational Psychology Review 14(1), 71–86 (2002)'
        WHEN 41 THEN 'Science 333(6046), 1096–1097 (2011); PubMed und Nottingham-Autorenrepository'
        ELSE NULL END,
      c.page_or_section=CASE s.citation_number
        WHEN 32 THEN 'Verlagsabstract; Schluesselbegriffe treatment, representation conversion; Seitenbelege in Gesamttext nachpruefen'
        WHEN 33 THEN 'Originalabstract, Vergleich diagrammatischer und sententieller Repraesentationen'
        WHEN 34 THEN 'Verlagsabstract: Visualisierung als Produkt/Prozess, Moeglichkeiten und Grenzen'
        WHEN 35 THEN 'Universitaetsrepository-Abstract zum DeFT-Rahmen: Design, Functions, Tasks'
        WHEN 36 THEN 'Originalabstract: Integration verbaler/bildlicher Repr.; 60 Studierende in drei Experimentalbedingungen'
        WHEN 37 THEN 'ERIC-Verlagsabstract: representation dilemma, Repraesentationskompetenz, Vergleich ein/multiple Visualisierungen'
        WHEN 38 THEN 'IHMC-Originalfassung: Einleitung; Begriff/Proposition; Focus Question; Cross-Links'
        WHEN 39 THEN 'Originalabstract: 55 Studien, 5818 Teilnehmende, 67 standardisierte Effektgroessen; Heterogenitaet'
        WHEN 40 THEN 'Universitaets-Forschungsrepository: Abstract, Wissenserinnerung, Vorwissen, aktive Verarbeitung'
        WHEN 41 THEN 'Autorenrepository: Essay/kurzer Fachbeitrag zu eigenstaendigem Zeichnen beim Naturwissenschaftslernen'
        ELSE NULL END,
      c.assessment=CASE s.citation_number
        WHEN 32 THEN 'Duvals Unterscheidung von Registerwechsel (conversion) und registerinterner Bearbeitung (treatment) im Verlagsabstract thematisch und durch Schluesselbegriffe gestuetzt; exakten Haupttextbeleg fuer jede Begriffsdefinition noch pruefen.'
        WHEN 33 THEN 'Originalabstract belegt informationsaequivalente Darstellungen und potenziell unterschiedliche rechnerische Effizienz; keine allgemeine Ueberlegenheit aller Diagramme. S. 65–100 fuer konkrete Aufgabenbeispiele noch abgleichen.'
        WHEN 34 THEN 'Visualisierung als Herstellung, Interpretation und Reflexion bildlicher Darstellungen sowie ihre moeglichen Grenzen im Springer-Abstract unmittelbar belegt; konkrete Beispiele und ihre Reichweite im Volltext offen.'
        WHEN 35 THEN 'DeFT (Design, Functions, Tasks) wird im Autorenrepository klar beschrieben. Die Dreiteilung der Funktionen complement/constrain/construct ist fuer den exakten Wortlaut an den Artikelabschnitten zu pruefen.'
        WHEN 36 THEN 'Der experimentelle Vergleich mit sechzig Studierenden, drei Bedingungen und mentaler Modellbildung ist im Verlagsabstract unmittelbar belegt. Effektinterpretation und Detailbefunde noch im Gesamttext pruefen.'
        WHEN 37 THEN 'Forschungsueberblick und Annahme, dass Vorteile multipler Visualisierungen von Repraesentationskompetenz abhaengen koennen, im Abstract gestuetzt. Kein allgemeiner Effekt fuer FRZK; sieben Hypothesen im Volltext pruefen.'
        WHEN 38 THEN 'Begriffe, beschriftete Beziehungen, Aussagen, hierarchische Gliederung, Querverbindungen und Leitfragen sind direkt im offiziellen IHMC-Text erklaert. Keine automatische Geltung der FRZK-Rechenregeln aus Concept-Maps.'
        WHEN 39 THEN 'Alle drei exakten Stichproben-/Effektzahlen sind im Verlagsabstract bestaetigt. Wissenserhalt verbessert in mehreren Vergleichsbedingungen; signifikante Heterogenitaet verhindert generalisierende Ueberlegenheit. Methodendetails im Volltext offen.'
        WHEN 40 THEN 'Review zum Wissenserhalt zentraler Ideen, besonderem Nutzen bei niedrigem Vorwissen/verbaler Faehigkeit sowie aktiver Bearbeitung ist direkt durch Universitaetsabstract belegt. Uebertragbarkeit auf FRZK-Mathematik nicht belegt.'
        WHEN 41 THEN 'Die Rolle aktiven Zeichnens im naturwissenschaftlichen Lernen wird argumentativ dargestellt; es ist ein zweiseitiger Perspektivbeitrag, KEINE unabhaengige experimentelle Studie zu FRZK und kein kausaler Wirksamkeitsbeleg.'
        ELSE NULL END
  WHERE d.section_code='2.2' AND s.citation_number BETWEEN 32 AND 41 AND c.review_status='open';
  IF ROW_COUNT() <> 10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 CLAIMS UPDATE COUNT FAIL'; END IF;
  SELECT COUNT(*) INTO v_sources
    FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
    WHERE s.citation_number BETWEEN 32 AND 41 AND r.review_status='in_review'
      AND r.evidence_uri IS NOT NULL AND r.metadata_comparison IS NOT NULL
      AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims
    FROM rkb2_ch2_claim_review c JOIN source_usage u ON u.usage_id=c.usage_id
    JOIN dissertation_sections d ON d.section_id=u.section_id
    JOIN sources s ON s.source_id=u.source_id
    WHERE d.section_code='2.2' AND s.citation_number BETWEEN 32 AND 41
      AND c.review_status='in_review' AND c.assessment IS NOT NULL
      AND c.page_or_section IS NOT NULL AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources<>10 OR v_claims<>10 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.2 POSTSTATE AUDIT FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_22_EVIDENCE_PRESTAGED' AS check_code, 'PASS' AS result,
         v_sources AS sources_in_review, v_claims AS claims_in_review,
         'Provisional evidence only; scientific gates OPEN.' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_23` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135 OR
