    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 AUDIT REGISTER COUNT DIFFERS';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u
      JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id
      JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
      JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
      WHERE d.section_code='2.3' AND s.citation_number BETWEEN 42 AND 55) <> 14 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 SOURCE-USAGE INTEGRITY FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l
      JOIN dissertation_sections d ON d.section_id=l.section_id
      WHERE d.section_code='2.3' AND l.object_type='manuscript'
      AND BINARY SHA2(l.new_value,256)=BINARY '0e1b807d6b0d4ffc133c80dd482a1fc143c9b2b39becec5598ce0a66fa15823e') <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 IMPORT TEXT SHA FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
      WHERE s.citation_number BETWEEN 42 AND 55 AND (
        r.review_status <> 'open' OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
        OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31), s.source_key,s.full_citation_text,
                 COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 SOURCE REVIEW STALE OR NOT OPEN';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c JOIN source_usage u ON u.usage_id=c.usage_id
      JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id
      WHERE d.section_code='2.3' AND s.citation_number BETWEEN 42 AND 55 AND (
        c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
        OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),
                COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 CLAIM REVIEW STALE OR NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.0' AND review_status='in_review') <> 4 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.1' AND review_status='in_review') <> 13 OR
