        WHEN 54 THEN 'Statistische Einzelresultate und Unterschiede zwischen Unterrichtsbedingungen im Volltext nachpruefen.'
        WHEN 55 THEN 'Der Originalartikel ist fuer genaue Begriffsabgrenzungen und Zitate im Volltext nachzupruefen.'
        ELSE NULL END
  WHERE s.citation_number BETWEEN 42 AND 55 AND r.review_status='open';
  IF ROW_COUNT() <> 14 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 SOURCES UPDATE COUNT FAIL';
  END IF;

  UPDATE rkb2_ch2_claim_review c
