  JOIN sources s ON s.source_id=u.source_id
  JOIN dissertation_sections d ON d.section_id=u.section_id
  SET c.review_status='in_review',
      c.evidence_uri=CASE s.citation_number
        WHEN 42 THEN 'https://press.princeton.edu/books/paperback/9780691164076/how-to-solve-it'
        WHEN 43 THEN 'https://doi.org/10.1016/C2013-0-05012-8'
        WHEN 44 THEN 'https://jwilson.coe.uga.edu/EMAT7050/Schoenfeld_MathThinking.pdf'
        WHEN 45 THEN 'https://eric.ed.gov/?id=EJ313052'
        WHEN 46 THEN 'https://doi.org/10.1016/0959-4752(94)90002-7'
