        WHEN 48 THEN 'https://doi.org/10.1207/s15516709cog1202_4'
        WHEN 49 THEN 'https://www.nationalacademies.org/read/9822/chapter/6'
        WHEN 50 THEN 'https://doi.org/10.1007/s10648-015-9302-x'
        WHEN 51 THEN 'https://reasoninglab.psych.ucla.edu/wp-content/uploads/sites/273/2021/04/Gick_Holyoak1983_SchemaInduction.pdf'
        WHEN 52 THEN 'https://pubmed.ncbi.nlm.nih.gov/12081085/'
        WHEN 53 THEN 'https://doi.org/10.1207/s15327809jls1504_1'
        WHEN 54 THEN 'https://eric.ed.gov/?id=EJ953699'
        WHEN 55 THEN 'https://www.jstor.org/stable/30034943'
        ELSE NULL END,
      c.edition_or_version=CASE s.citation_number
        WHEN 42 THEN 'Pólya, How to Solve It; 1957 zweite Auflage (Verlags-Neuausgabe mit eigener ISBN moeglich)'
        WHEN 43 THEN 'Schoenfeld (1985), Mathematical Problem Solving, Academic Press, Elsevier Monografie'
        WHEN 44 THEN 'Schoenfeld (1992), Handbook of Research on Mathematics Teaching and Learning, 334–370'
        WHEN 45 THEN 'Kintsch und Greeno (1985), Psychological Review 92(1), 109–129'
        WHEN 46 THEN 'Verschaffel, De Corte, Lasure (1994), Learning and Instruction 4(4), 273–294'
        WHEN 47 THEN 'Verschaffel, Greer, De Corte (2000), Making Sense of Word Problems, Swets & Zeitlinger, Lisse'
        WHEN 48 THEN 'Sweller (1988), Cognitive Science 12(2), 257–285'
        WHEN 49 THEN 'National Research Council (2001), Adding It Up, NAP DOI 10.17226/9822'
        WHEN 50 THEN 'Rittle-Johnson, Schneider, Star (2015), Educational Psychology Review 27(4), 587–597'
        WHEN 51 THEN 'Gick und Holyoak (1983), Cognitive Psychology 15(1), 1–38'
        WHEN 52 THEN 'Barnett und Ceci (2002), Psychological Bulletin 128(4), 612–637'
        WHEN 53 THEN 'Lobato (2006), Journal of the Learning Sciences 15(4), 431–449'
        WHEN 54 THEN 'Schukajlow, Leiss, Pekrun, Blum, Mueller, Messner (2012), ESM 79(2), 215–237'
        WHEN 55 THEN 'Star (2005), Journal for Research in Mathematics Education 36(5), 404–411'
        ELSE NULL END,
      c.page_or_section=CASE s.citation_number
        WHEN 42 THEN 'Vier-Phasen-Zusammenfassung: Understand, Plan, Carry out, Look back. 1957-Ausgabe im Original noch abgleichen'
        WHEN 43 THEN 'Verlagsbeschreibung und Inhaltsverzeichnis, Kapitel 1 bis 5 (Resources, Heuristics, Control, Beliefs)'
        WHEN 44 THEN 'Autorenmanuskript PDF, Titelseite mit bibliografischer Angabe, Haupttext zur Metakognition'
        WHEN 45 THEN 'ERIC Abstract: mental representations, text comprehension, problem solving'
        WHEN 46 THEN 'Elsevier Abstract: 10 Aufgabenpaare und 75 Kinder aus Klasse 5; Reaktionen auf realistische Aufgaben'
        WHEN 47 THEN 'WorldCat Titel-, Autoren- und Verlagsdatensatz, zusaetzlich Buchbeschreibung bei Google Books'
        WHEN 48 THEN 'Wiley Originalabstract: means-ends, schema acquisition, cognitive processing capacity'
        WHEN 49 THEN 'Originalbericht Kapitel 4, The Strands of Mathematical Proficiency, S. 116 ff.'
        WHEN 50 THEN 'Springer Abstract, bidirektionale Entwicklung von prozeduralem und konzeptuellem Wissen'
        WHEN 51 THEN 'Autoren-PDF, Abstract und experimentelle Teile I und II'
        WHEN 52 THEN 'PubMed Originalabstract: 9 Transferdimensionen; heterogene Bedingungen'
        WHEN 53 THEN 'Taylor & Francis Verlagsseite und Originalabstract, Transferperspektiven'
        WHEN 54 THEN 'ERIC Abstract: DISUM; 224 Neuntklaessler in 14 Realschulklassen; 10 Unterrichtsstunden'
        WHEN 55 THEN 'JSTOR Heft-Inhaltsverzeichnis und Fachbeitrag Research Commentary'
        ELSE NULL END,
      c.assessment=CASE s.citation_number
        WHEN 42 THEN 'Vier Phasen des heuristischen Problemloesens sind etablierte Inhalte. Keine FRZK-spezifische Wirksamkeit aus Pólya ableitbar.'
        WHEN 43 THEN 'Vier Kategorien Ressourcen, Heuristiken, Kontrolle und Ueberzeugungen in Verlagsbeschreibung und Inhaltsverzeichnis explizit bestaetigt.'
        WHEN 44 THEN 'Originalmanuskript behandelt Problemloesen, Metakognition und Sense-Making. Selbststeuerung ist fachliche Interpretation; genaue Unterstellen vor Freigabe pruefen.'
        WHEN 45 THEN 'Verstaendnis sprachlicher Textaufgaben und mehrstufige mentale Repraesentationen durch Fachabstract explizit gedeckt.'
        WHEN 46 THEN 'Empirische geringe Beruecksichtigung der Sachrealitaet in problematischen Textaufgaben direkt im Abstract belegt. Keine Verallgemeinerung auf alle Altersgruppen oder FRZK.'
        WHEN 47 THEN 'Das Buch behandelt Sinnverstaendnis und Unterrichtskonventionen bei Textaufgaben. Konkrete Kapitelbelege fuer einzelne Behauptungen offen.'
        WHEN 48 THEN 'Hohe Belastung bei konventionellem Means-Ends-Problemloesen und Risiko fuer Schemabildung werden im Abstract direkt diskutiert. FRZK-Wirkung ungetestet.'
        WHEN 49 THEN 'Fuenf verflochtene Komponenten konzeptuell, prozedural, strategisch, adaptiv und Haltung im frei zugaenglichen Volltext explizit bestaetigt.'
        WHEN 50 THEN 'Der Forschungsueberblick argumentiert fuer bidirektionale Beziehungen zwischen beiden Wissensformen. Kein spezifischer empirischer Test von FRZK.'
        WHEN 51 THEN 'Schemaabstraktion und analoger Transfer sind belegt; wichtig: einzelne Instruktionshilfen in Teil I waren nicht erfolgreich, zwei Analogien in Teil II foerderten Schemainduktion.'
        WHEN 52 THEN 'Transfer wird entlang neun Dimensionen klassifiziert. Eine einzige pauschale Effektgroesse fuer Ferntransfer ist nach Autoren unzweckmaessig.'
        WHEN 53 THEN 'Unterschiedliche theoretische und methodische Transferverstaendnisse sowie offene Forschungsfragen werden behandelt.'
        WHEN 54 THEN 'Studie behandelt aufgabenbezogene Freude, Interesse, Wert und Selbstwirksamkeit bei Modellierungsaufgaben. Keine allgemeine kausale Wirkung des FRZK.'
        WHEN 55 THEN 'Star diskutiert flexibles und differenziertes prozedurales Wissen; es handelt sich um einen Research Commentary, NICHT um eigenstaendige Wirksamkeitsstudie.'
        ELSE NULL END
  WHERE d.section_code='2.3' AND s.citation_number BETWEEN 42 AND 55
    AND c.review_status='open';
  IF ROW_COUNT() <> 14 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 CLAIMS UPDATE COUNT FAIL';
  END IF;
  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review r
    JOIN sources s ON s.source_id=r.source_id
    WHERE s.citation_number BETWEEN 42 AND 55 AND r.review_status='in_review'
      AND r.evidence_uri IS NOT NULL AND r.metadata_comparison IS NOT NULL
      AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review c
    JOIN source_usage u ON u.usage_id=c.usage_id
    JOIN dissertation_sections d ON d.section_id=u.section_id
    JOIN sources s ON s.source_id=u.source_id
    WHERE d.section_code='2.3' AND s.citation_number BETWEEN 42 AND 55
      AND c.review_status='in_review' AND c.assessment IS NOT NULL
      AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources <> 14 OR v_claims <> 14 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.3 IN_REVIEW POSTSTATE FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_23_EVIDENCE_PRESTAGED' AS check_code, 'PASS' AS result,
    v_sources AS sources_in_review, v_claims AS claims_in_review,
    'Provisional evidence only. No scientific clearance.' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_24` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135
     OR (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 REGISTER COUNT DIFFERENCE';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u
      JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id
      JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
      JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
      WHERE d.section_code='2.4' AND s.citation_number BETWEEN 56 AND 69) <> 14 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 SOURCE USAGE INTEGRITY';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l
      JOIN dissertation_sections d ON d.section_id=l.section_id
      WHERE d.section_code='2.4' AND l.object_type='manuscript'
      AND BINARY SHA2(l.new_value,256)=BINARY 'b4f9c21d9de2c7c3bbcc3177bf378ae7470763c1d056cd99b64a9a2355217f8c') <> 1 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 IMPORT TEXT HASH';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r
      JOIN sources s ON s.source_id=r.source_id
      WHERE s.citation_number BETWEEN 56 AND 69 AND
        (r.review_status <> 'open' OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
         OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,
            s.full_citation_text,COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 SOURCE REVIEW STALE';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c
      JOIN source_usage u ON u.usage_id=c.usage_id
      JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id
      WHERE d.section_code='2.4' AND s.citation_number BETWEEN 56 AND 69 AND
        (c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
         OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),
            COALESCE(u.claim_summary,''),COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 CLAIM REVIEW STALE';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='in_review') <> 41
     OR (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='open') <> 100 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 PRIOR AUDIT COUNTS';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.4' AND review_status='open') <> 14 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 TARGET NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code IN ('2.0','2.1','2.2','2.3')
     AND review_status='in_review') <> 41 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 PREVIOUS REVIEWS INCOMPLETE';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
      WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND u.citation_checked=1) <> 0
     OR (SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 15 AND 149 AND verification_status='verified') <> 0 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 SCIENTIFIC FIELDS NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND status='draft') <> 12 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 CHAPTER NOT DRAFT';
  END IF;

  START TRANSACTION;
  UPDATE rkb2_ch2_source_review r
  JOIN sources s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CASE s.citation_number
      WHEN 56 THEN 'https://search.worldcat.org/title/441295'
      WHEN 57 THEN 'https://www.nationalacademies.org/read/9853/chapter/5'
      WHEN 58 THEN 'https://pubmed.ncbi.nlm.nih.gov/16026503/'
      WHEN 59 THEN 'https://doi.org/10.1207/s15327809jls0302_1'
      WHEN 60 THEN 'https://cris.huji.ac.il/en/publications/concept-image-and-concept-definition-in-mathematics-with-particul/'
      WHEN 61 THEN 'https://doi.org/10.1007/0-306-47203-1_5'
      WHEN 62 THEN 'https://link.springer.com/article/10.1007/BF00302715'
      WHEN 63 THEN 'https://siegler.tc.columbia.edu/wp-content/uploads/2020/10/2001-Siegler-Alibali.pdf'
      WHEN 64 THEN 'https://psych.wisc.edu/alibali/home/Publications_files/Knuth_Stephens_McNeil_Alibali_JRME_2006.pdf'
      WHEN 65 THEN 'https://escholarship.org/uc/item/3b61n1wd'
      WHEN 66 THEN 'https://link.springer.com/article/10.1007/s13394-013-0079-2'
      WHEN 67 THEN 'https://link.springer.com/article/10.1007/s13394-019-00258-1'
      WHEN 68 THEN 'https://www.jstor.org/stable/jj.33169475'
      WHEN 69 THEN 'https://doi.org/10.1207/S15326985EP3801_6'
      ELSE NULL END,
      r.edition_or_version=CASE s.citation_number
      WHEN 56 THEN 'Ausubel, Educational Psychology: A Cognitive View (1968), Holt, Rinehart and Winston'
      WHEN 57 THEN 'National Research Council (2000), How People Learn, Expanded Edition, National Academies Press, DOI 10.17226/9853'
      WHEN 58 THEN 'McNeil und Alibali (2005), Child Development 76(4), 883–899; DOI 10.1111/j.1467-8624.2005.00884.x'
      WHEN 59 THEN 'Smith III, diSessa, Roschelle, Journal of the Learning Sciences 3(2), 115–163, Ausgabe 1994'
      WHEN 60 THEN 'Tall und Vinner (1981), Educational Studies in Mathematics 12(2), 151–169; DOI 10.1007/BF00305619'
      WHEN 61 THEN 'Vinner (1991), in Tall (Hrsg.), Advanced Mathematical Thinking, Seiten 65–81'
      WHEN 62 THEN 'Sfard (1991), Educational Studies in Mathematics 22, 1–36'
      WHEN 63 THEN 'Rittle-Johnson, Siegler, Alibali (2001), Journal of Educational Psychology 93(2), 346–362'
      WHEN 64 THEN 'Knuth, Stephens, McNeil, Alibali (2006), JRME 37(4), 297–312'
      WHEN 65 THEN 'Moschkovich (2015), Journal of Mathematical Behavior 40, 43–62, DOI 10.1016/j.jmathb.2015.01.005'
      WHEN 66 THEN 'Prediger und Wessel (2013), Mathematics Education Research Journal 25, 435–456'
      WHEN 67 THEN 'Prediger (2019), Mathematics Education Research Journal 31, 367–392'
      WHEN 68 THEN 'Mercer (1995), The Guided Construction of Knowledge, Multilingual Matters'
      WHEN 69 THEN 'Mayer und Moreno (2003), Educational Psychologist 38(1), 43–52'
      ELSE NULL END,
      r.metadata_comparison=CASE s.citation_number
      WHEN 56 THEN 'WorldCat und Google Books bestaetigen Autor, Titel, Jahr, Verlag. Volltext-Passage zu Subsumption und Vorwissen noch nicht durch Originalseiten gesichert.'
      WHEN 57 THEN 'NAP-Volltext bestaetigt Ausgabe 2000 und Herausgebergruppen. Originalausgabe von 1999 unterscheiden.'
      WHEN 58 THEN 'PubMed und Wiley bestaetigen Publikation; zwei Experimente und operational patterns im Abstract.'
      WHEN 59 THEN 'Verlagsheft nennt Jahr 1994; SRI/Autorenrepositorien zum Teil 1993. Editions-/Online-Datumsunterschied vor Freigabe festhalten.'
      WHEN 60 THEN 'Universitaetsportal und ERIC geben Heft 12(2) an. Warwick-Repositorium fuehrt irrtuemlich No.7; nicht uebernehmen.'
      WHEN 61 THEN 'Springer-Buchinhaltsverzeichnis bestaetigt Autor, Beitrag und Seiten; Originalkapitel fuer detaillierte didaktische Aussagen noch lesen.'
      WHEN 62 THEN 'Springer Originalabstract und Heftangaben bestaetigen Publikation.'
      WHEN 63 THEN 'Autoren-PDF zeigt Titel, Jahrgang, DOI und Abstract; zwei Experimente in Jahrgangsstufen 5/6.'
      WHEN 64 THEN 'Autoren-PDF nennt Vol.37 No.4. ERIC-Datensatz fuehrt irrtuemlich v36; Primaer-PDF hat Vorrang.'
      WHEN 65 THEN 'Universitaetsrepositorium liefert bibliografische Metadaten und Abstract; kein eigener FRZK-Test.'
      WHEN 66 THEN 'Springer Open Access belegt Jahr, Autorinnen, Seiten und Studiendesign.'
      WHEN 67 THEN 'Springer Open Access belegt Metadaten und designbasierte Studie zur Lehrkraftqualifizierung.'
      WHEN 68 THEN 'JSTOR/WorldCat bestaetigen Buchjahr 1995, Originalverlag und Autor. Kapitelbezogene Textstellen offen.'
      WHEN 69 THEN 'Taylor & Francis Artikelmetadaten; Online-Einstelldatum 2010 von Printjahr 2003 trennen.'
      ELSE NULL END
  WHERE s.citation_number BETWEEN 56 AND 69 AND r.review_status='open';
  IF ROW_COUNT() <> 14 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 SOURCES UPDATE COUNT';
  END IF;

  UPDATE rkb2_ch2_claim_review c
  JOIN source_usage u ON u.usage_id=c.usage_id
  JOIN sources s ON s.source_id=u.source_id
  JOIN dissertation_sections d ON d.section_id=u.section_id
  SET c.review_status='in_review',
      c.evidence_uri=CASE s.citation_number
      WHEN 56 THEN 'https://search.worldcat.org/title/441295'
      WHEN 57 THEN 'https://www.nationalacademies.org/read/9853/chapter/5'
      WHEN 58 THEN 'https://pubmed.ncbi.nlm.nih.gov/16026503/'
      WHEN 59 THEN 'https://doi.org/10.1207/s15327809jls0302_1'
      WHEN 60 THEN 'https://cris.huji.ac.il/en/publications/concept-image-and-concept-definition-in-mathematics-with-particul/'
      WHEN 61 THEN 'https://doi.org/10.1007/0-306-47203-1_5'
      WHEN 62 THEN 'https://link.springer.com/article/10.1007/BF00302715'
      WHEN 63 THEN 'https://siegler.tc.columbia.edu/wp-content/uploads/2020/10/2001-Siegler-Alibali.pdf'
      WHEN 64 THEN 'https://psych.wisc.edu/alibali/home/Publications_files/Knuth_Stephens_McNeil_Alibali_JRME_2006.pdf'
      WHEN 65 THEN 'https://escholarship.org/uc/item/3b61n1wd'
      WHEN 66 THEN 'https://link.springer.com/article/10.1007/s13394-013-0079-2'
      WHEN 67 THEN 'https://link.springer.com/article/10.1007/s13394-019-00258-1'
      WHEN 68 THEN 'https://www.jstor.org/stable/jj.33169475'
      WHEN 69 THEN 'https://doi.org/10.1207/S15326985EP3801_6'
      ELSE NULL END,
      c.edition_or_version=CASE s.citation_number
      WHEN 56 THEN 'Ausubel, Educational Psychology: A Cognitive View (1968), Holt, Rinehart and Winston'
      WHEN 57 THEN 'National Research Council (2000), How People Learn, Expanded Edition, National Academies Press, DOI 10.17226/9853'
      WHEN 58 THEN 'McNeil und Alibali (2005), Child Development 76(4), 883–899; DOI 10.1111/j.1467-8624.2005.00884.x'
      WHEN 59 THEN 'Smith III, diSessa, Roschelle, Journal of the Learning Sciences 3(2), 115–163, Ausgabe 1994'
      WHEN 60 THEN 'Tall und Vinner (1981), Educational Studies in Mathematics 12(2), 151–169; DOI 10.1007/BF00305619'
      WHEN 61 THEN 'Vinner (1991), in Tall (Hrsg.), Advanced Mathematical Thinking, Seiten 65–81'
      WHEN 62 THEN 'Sfard (1991), Educational Studies in Mathematics 22, 1–36'
      WHEN 63 THEN 'Rittle-Johnson, Siegler, Alibali (2001), Journal of Educational Psychology 93(2), 346–362'
      WHEN 64 THEN 'Knuth, Stephens, McNeil, Alibali (2006), JRME 37(4), 297–312'
      WHEN 65 THEN 'Moschkovich (2015), Journal of Mathematical Behavior 40, 43–62, DOI 10.1016/j.jmathb.2015.01.005'
      WHEN 66 THEN 'Prediger und Wessel (2013), Mathematics Education Research Journal 25, 435–456'
      WHEN 67 THEN 'Prediger (2019), Mathematics Education Research Journal 31, 367–392'
      WHEN 68 THEN 'Mercer (1995), The Guided Construction of Knowledge, Multilingual Matters'
      WHEN 69 THEN 'Mayer und Moreno (2003), Educational Psychologist 38(1), 43–52'
      ELSE NULL END,
      c.page_or_section=CASE s.citation_number
      WHEN 56 THEN 'Google Books bibliografische Angaben; WorldCat Buchbeschreibung; Originalseiten offen'
      WHEN 57 THEN 'NAP Kapitel 2: How Experts Differ from Novices; Kapitel 1: Learning: From Speculation to Science'
      WHEN 58 THEN 'PubMed Originalabstract: Experiment 1, Kinder 7 bis 11 Jahre; Experiment 2, Studierende'
      WHEN 59 THEN 'Taylor and Francis Abstract; SRI Zusammenfassung'
      WHEN 60 THEN 'Universitaets-Repositorium, Abstract: concept image und concept definition; limits and continuity'
      WHEN 61 THEN 'Springer Buchinhalt, Kapitel The Role of Definitions in the Teaching and Learning of Mathematics, 65–81'
      WHEN 62 THEN 'Springer Originalabstract: structural-as-objects und operationally-as-processes'
      WHEN 63 THEN 'Autoren-PDF Titelseite/Abstract: Experiment 1 und Experiment 2'
      WHEN 64 THEN 'Autoren-PDF Titelseite und Abstract; Mittelstufenschueler, Gleichheitsverstaendnis'
      WHEN 65 THEN 'eScholarship Originalabstract: proficiency, practices, discourse; classroom discussion'
      WHEN 66 THEN 'Springer Abstract und Abschnitte zur sprachlich-mathematisch integrierten Bruchzahlintervention'
      WHEN 67 THEN 'Springer Abstract, Methode und Diskussion language-responsive teaching'
      WHEN 68 THEN 'JSTOR Verlagsbeschreibung: Unterrichtsgespraeche und gemeinsame Wissenskonstruktion'
      WHEN 69 THEN 'Taylor & Francis Originalabstract: dual channel, limited capacity, active processing und Ueberlastung'
      ELSE NULL END,
      c.assessment=CASE s.citation_number
      WHEN 56 THEN 'Vorwissen und sinnvolles Lernen sind etablierter Ausubel-Bezug. Die zusaetzliche Schlussfolgerung ueber die FRZK-Anwendung ist eine eigene didaktische Ableitung.'
      WHEN 57 THEN 'Einfluss vorhandener Wissensstrukturen und Unterscheidung Experten/Novizen im Volltext behandelt. FRZK-spezifischer Nutzen nicht aus der Quelle ableitbar.'
      WHEN 58 THEN 'Uebertragene arithmetische Muster beeintraechtigen Gleichungsverstaendnis; negative Beziehung und experimentelle Aktivierung im Abstract beschrieben. Keine allgemeine FRZK-Wirksamkeit.'
      WHEN 59 THEN 'Vorstellungen als produktive Ressourcen, Verfeinerung statt blosser Ersetzung im Abstract und SRI-Zusammenfassung gestuetzt. Kein spezifisches FRZK-Didaktikergebnis.'
      WHEN 60 THEN 'Abweichung individueller Begriffsauffassung von formalen Definitionen bei Grenzwerten/Stetigkeit direkt im Abstract gestuetzt.'
      WHEN 61 THEN 'Verhaeltnis zwischen verwendeter Definition und aktivierter Begriffsauffassung als Schwerpunkt plausibel; genaue Behauptungen erst nach Kapitelstellenabgleich final.'
      WHEN 62 THEN 'Komplementaritaet operationaler und struktureller Auffassungen und ihre Rolle im mathematischen Lernen explizit im Abstract bestaetigt.'
      WHEN 63 THEN 'Bidirektionale Entwicklung konzeptuellen und prozeduralen Wissens bei Dezimalzahlen durch Experimente gestuetzt; Generalisierung auf FRZK nicht getestet.'
      WHEN 64 THEN 'Zusammenhang zwischen relationalem Gleichheitsverstaendnis und Gleichungsloesen in Originalabstract belegt, auch nach Kontrolle der Mathematikleistung.'
      WHEN 65 THEN 'Mathematische Sprachkompetenz mit drei verbundenen Komponenten fachlich gestuetzt; FRZK-Bezug ist eine Folgerung des Autors.'
      WHEN 66 THEN 'Integrierte Intervention bei Bruchzahlen und pretest-posttest-kontrolliertes Design belegt. Effektstaerken nur fuer konkrete Studie; nicht auf FRZK uebertragbar.'
      WHEN 67 THEN 'Fachbezogene sprachsensible Lehrerexpertise und Professionalisierung empirisch thematisiert; genaue Anteile von Designs/Intervention im Volltext pruefen.'
      WHEN 68 THEN 'Gespräche als Medium gemeinsamer Bedeutungsbildung durch Verlagsbeschreibung gestuetzt; detaillierte Unterrichtsbeispiele nur nach Seitenpruefung.'
      WHEN 69 THEN 'Theoretischer kognitiver Multimedia-Rahmen und Strategien zur Lastreduktion fachlich gestuetzt; kein direkter empirischer Nachweis fuer das FRZK.'
      ELSE NULL END
  WHERE d.section_code='2.4' AND s.citation_number BETWEEN 56 AND 69 AND c.review_status='open';
  IF ROW_COUNT() <> 14 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 CLAIMS UPDATE COUNT';
  END IF;
  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review r
     JOIN sources s ON s.source_id=r.source_id
     WHERE s.citation_number BETWEEN 56 AND 69 AND r.review_status='in_review'
     AND r.evidence_uri IS NOT NULL AND r.edition_or_version IS NOT NULL
     AND r.metadata_comparison IS NOT NULL AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review c
     JOIN source_usage u ON u.usage_id=c.usage_id
     JOIN dissertation_sections d ON d.section_id=u.section_id
     JOIN sources s ON s.source_id=u.source_id
     WHERE d.section_code='2.4' AND s.citation_number BETWEEN 56 AND 69
     AND c.review_status='in_review' AND c.evidence_uri IS NOT NULL
     AND c.page_or_section IS NOT NULL AND c.assessment IS NOT NULL
     AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources <> 14 OR v_claims <> 14 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.4 POSTSTATE REVIEW FAILED';
  END IF;
  COMMIT;
  SELECT 'SECTION_24_EVIDENCE_PRESTAGED' AS check_code, 'PASS' AS result,
         v_sources AS sources_in_review, v_claims AS claims_in_review,
         'Preliminary only: GATE_05 remains BLOCKED.' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_25` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  -- Fachliche Einzel- und Hashpruefung bleibt OPEN; Ausgangszustand streng pruefen.
  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135
    OR (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 REGISTER COUNTS DIFFER';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='in_review') <> 55
    OR (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='open') <> 86
    OR (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='supported') <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 PREVIOUS REVIEW COUNT FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.5' AND review_status='open') <> 16
    OR (SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
        WHERE s.citation_number BETWEEN 70 AND 85 AND r.review_status='open') <> 16 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 TARGET REVIEWS NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u
      JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id
      JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
      JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
      WHERE d.section_code='2.5' AND s.citation_number BETWEEN 70 AND 85) <> 16 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 USAGE AND REVIEWS NOT EXACTLY 16';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l
      JOIN dissertation_sections d ON d.section_id=l.section_id
      WHERE d.section_code='2.5' AND l.object_type='manuscript'
      AND BINARY SHA2(l.new_value,256)=BINARY 'c38f6ff1362035926324b94374337e44336d0dc36c806c02f88a79b73ba6a314') <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 IMPORT MANUSCRIPT SHA256 FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r
      JOIN sources s ON s.source_id=r.source_id
      WHERE s.citation_number BETWEEN 70 AND 85
      AND (r.review_status <> 'open' OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
      OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),
           s.source_key,s.full_citation_text,COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 SOURCE REVIEW FINGERPRINT STALE';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c
      JOIN source_usage u ON u.usage_id=c.usage_id
      JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id
      WHERE d.section_code='2.5' AND s.citation_number BETWEEN 70 AND 85
      AND (c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
      OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),
           COALESCE(u.claim_summary,''),COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 CLAIM REVIEW FINGERPRINT STALE';
  END IF;
  IF (SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND status='draft') <> 12
      OR (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
          WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND u.citation_checked=1) <> 0
      OR (SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 15 AND 149 AND verification_status='verified') <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 SCIENTIFIC RELEASE STATE MODIFIED';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code IN ('2.0','2.1','2.2','2.3','2.4') AND review_status='in_review') <> 55 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 PREVIOUS SECTIONS NOT COMPLETE';
  END IF;

  START TRANSACTION;
