      WHEN 81 THEN 'Wisniewski, Zierer, Hattie, online 22.01.2020, Frontiers in Psychology Band 10 (2019), Art. 3087'
      WHEN 82 THEN 'Kluger und DeNisi (1996), Psychological Bulletin 119(2), 254-284'
      WHEN 83 THEN 'Butler (1988), British Journal of Educational Psychology 58(1), 1-14'
      WHEN 84 THEN 'Renkl (2002), Learning and Instruction 12(5), 529-556'
      WHEN 85 THEN 'Kalyuga, Ayres, Chandler, Sweller (2003), Educational Psychologist 38(1), 23-31'
      ELSE NULL END,
      c.page_or_section=CASE s.citation_number
      WHEN 70 THEN 'Kapitel Interaction Between Learning and Development; Buchinhaltsverzeichnis; Verlagsbeschreibung'
      WHEN 71 THEN 'Wiley Originalpublikation: Abstract und Theorie/Studienbeschreibung; sechs Scaffolding-Funktionen fuer FINAL im Volltext'
      WHEN 72 THEN 'Springer: Abstract und theoretischer Review; Contingency, Fading, Transfer of Responsibility'
      WHEN 73 THEN 'Abstract; Methods/Participants; Ergebnisse zur Wechselwirkung mit independent working time'
      WHEN 74 THEN 'SAGE Artikelinformationen; ERIC Abstract; Detailanalyse der zugrunde liegenden Vergleichsversuche offen'
      WHEN 75 THEN 'Wiley Originalabstract; Hypothesen tutor-centered, student-centered, interactive; zweite Studie'
      WHEN 76 THEN 'Verlagsabstract; Untergliederung answer-based, step-based, substep-based; Effektschaetzungen'
      WHEN 77 THEN 'Verlagsartikel und Hochschul-Forschungsportal; Review zur formativen Leistungsbewertung'
      WHEN 78 THEN 'Springer Originalabstract; theoretische Definition des formativen Feedbacks; Qualitaetskriterien'
      WHEN 79 THEN 'SAGE Abstract und Original-Volltext PDF; vier Feedbackebenen task/process/self-regulation/person'
      WHEN 80 THEN 'SAGE Originalabstract; Feedbacktypen von Richtigkeitsanzeige bis worked example'
      WHEN 81 THEN 'Frontiers Abstract; Results Identification of Studies; General Impact of Feedback; Citation'
      WHEN 82 THEN 'APA/EBSCO Originalabstract; Metaanalyse 607 Effektgroessen, 23663 Beobachtungen'
      WHEN 83 THEN 'Wiley Originalabstract: 12 Klassen, 132 ausgewaehlte Schueler, drei Bewertungsformen'
      WHEN 84 THEN 'ScienceDirect Originalabstract und Introduction; 20 Lehramtsstudierende Kontrollgruppe / 28 Intervention'
      WHEN 85 THEN 'Taylor & Francis Originalabstract; Expertise-Reversal-Effect, Vorwissen als Moderator'
      ELSE NULL END,
      c.assessment=CASE s.citation_number
      WHEN 70 THEN 'Unterscheidung zwischen selbstaendiger Leistung und Leistung unter Unterstuetzung entspricht der theoretischen ZPD-Konzeption. Kein experimenteller FRZK-Nachweis.'
      WHEN 71 THEN 'Funktionen abgestufter Unterstuetzung und Tutorrolle fachlich einschlaegig; ihre Uebertragung auf mathematische FRZK-Aufgaben ist eine didaktische Hypothese.'
      WHEN 72 THEN 'Drei Merkmale des Scaffolding sind ausdruecklich im Abstract genannt. Schwierigkeiten der Konzeptualisierung und empirischen Wirksamkeitsmessung bleiben relevant.'
      WHEN 73 THEN 'Nichtlineare Wechselwirkungen zwischen Contingency und Arbeitszeit bestaetigt; wegen Fach Gesellschaftskunde kein unmittelbarer empirischer Wirksamkeitsbeleg fuer Mathematik oder FRZK.'
      WHEN 74 THEN 'Einzelbetreuung und Frage nach vergleichbar effektivem Gruppenunterricht im Originaltitel und ERIC-Abstract belegt. Quantifizierte Ueberlegenheit nicht auf jede Nachhilfesituation uebertragen.'
      WHEN 75 THEN 'Vergleich dreier Mechanismen menschlichen Tutorings durch Originalabstract gestuetzt. Aktive Konstruktion und Interaktion koennen bedeutsam sein, ohne FRZK separat zu testen.'
      WHEN 76 THEN 'Review widerlegt starre Hierarchie vermeintlicher Effektgroessen: menschliches Tutoring d=0.79, ITS d=0.76 im Abstract. Unterschiedliche Vergleichsbedingungen beachten.'
      WHEN 77 THEN 'Formative Bewertung als Nutzung von Informationen ueber Lernen und Unterricht durch Grundwerk gestuetzt. Keine pauschale Kausalbeziehung fuer FRZK.'
      WHEN 78 THEN 'Theoretischer Zusammenhang von Qualitaetskriterien, Zielvorstellung, Ist-Zustand und Bearbeitungsanpassung plausibel; konkrete Passagen vor finalem Seitenbeleg lesen.'
      WHEN 79 THEN 'Konzeption verschiedener Feedbackebenen und variabler positiver/negativer Effekte fachlich gestuetzt. Personalisiertes Lob ist nicht mit Aufgabenfeedback gleichzusetzen.'
      WHEN 80 THEN 'Formative Rueckmeldung als lernbezogene Information, ihre Typen, Timing und Aufgabenspezifik sind durch Abstract gestuetzt; kein FRZK-Versuch.'
      WHEN 81 THEN 'Abstract berichtet d=0.48, der Abschnitt General Impact d=0.55 (gewichtete Random-Effects-Schaetzung; CI 0.48-0.62). Bezugswert der Manuskriptangabe d≈0.48 vor FINAL praezisieren, nicht unbemerkt gleichsetzen.'
      WHEN 82 THEN 'Im Abstract ist Verbesserung im Durchschnitt d=.41 bei Verschlechterungen in mehr als einem Drittel der Feedbackinterventionen belegt; nicht alle Lernkontexte oder FRZK direkt betroffen.'
      WHEN 83 THEN 'Im untersuchten Design waren individuelle Kommentare gegenueber Noten oder Noten+Kommentaren bezueglich Interesse/Leistung guenstiger; keine Generalisierung auf jede Mathematikaufgabe.'
      WHEN 84 THEN 'Positive Wirkung zusaetzlicher instruktiver Erklaerungen beim Selbsterklaeren unter bestimmten Bedingungen. Kleines Sample; didaktische Einordnung statt direkter FRZK-Effekt.'
      WHEN 85 THEN 'Mit steigendem Vorwissen koennen fuer Anfaenger hilfreiche Verfahren an Nutzen verlieren oder nachteilig sein; als Review kein experimenteller FRZK-Nachweis.'
      ELSE NULL END
  WHERE d.section_code='2.5' AND s.citation_number BETWEEN 70 AND 85 AND c.review_status='open';
  IF ROW_COUNT() <> 16 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 CLAIMS UPDATE COUNT FAIL';
  END IF;
  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review r
    JOIN sources s ON s.source_id=r.source_id
    WHERE s.citation_number BETWEEN 70 AND 85 AND r.review_status='in_review'
    AND r.evidence_uri IS NOT NULL AND r.edition_or_version IS NOT NULL
    AND r.metadata_comparison IS NOT NULL AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review c
    JOIN source_usage u ON u.usage_id=c.usage_id
    JOIN dissertation_sections d ON d.section_id=u.section_id
    JOIN sources s ON s.source_id=u.source_id
    WHERE d.section_code='2.5' AND s.citation_number BETWEEN 70 AND 85 AND c.review_status='in_review'
    AND c.evidence_uri IS NOT NULL AND c.edition_or_version IS NOT NULL
    AND c.page_or_section IS NOT NULL AND c.assessment IS NOT NULL
    AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources <> 16 OR v_claims <> 16 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.5 POSTSTATE COUNT FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_25_EVIDENCE_PRESTAGED' AS check_code,'PASS' AS result,
         v_sources AS sources_in_review,v_claims AS claims_in_review,
         'Preliminary only: GATE_05 remains BLOCKED' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_26` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 AUDIT REGISTER SIZE FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='in_review') <> 71 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='open') <> 70 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='supported') <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 PRIOR AUDIT STATE FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.6' AND review_status='open') <> 17 OR
     (SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
       WHERE s.citation_number BETWEEN 86 AND 102 AND r.review_status='open') <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 TARGET REVIEWS NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
      JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
      WHERE d.section_code='2.6' AND s.citation_number BETWEEN 86 AND 102) <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 USAGE REGISTRY NOT EXACT 17';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l JOIN dissertation_sections d ON d.section_id=l.section_id
      WHERE d.section_code='2.6' AND l.object_type='manuscript'
      AND BINARY SHA2(l.new_value,256)=BINARY '97b50e210b72ecd90d4959282e9ca5d3e11c7d54ef4b9fa1acaa019a63eba735') <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 IMPORT TEXT SHA256 FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
      WHERE s.citation_number BETWEEN 86 AND 102 AND (r.review_status <> 'open'
      OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
      OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,
         COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 SOURCE AUDIT FINGERPRINT FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c JOIN source_usage u ON u.usage_id=c.usage_id
      JOIN dissertation_sections d ON d.section_id=u.section_id JOIN sources s ON s.source_id=u.source_id
      WHERE d.section_code='2.6' AND s.citation_number BETWEEN 86 AND 102
      AND (c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
      OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),
         COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 CLAIM AUDIT FINGERPRINT FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND status='draft') <> 12 OR
     (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
      WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND u.citation_checked=1) <> 0 OR
     (SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 15 AND 149 AND verification_status='verified') <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 SCIENTIFIC GATE STATE CHANGED';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review
      WHERE section_code IN ('2.0','2.1','2.2','2.3','2.4','2.5') AND review_status='in_review') <> 71 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 PREVIOUS SECTIONS NOT COMPLETE';
  END IF;

  START TRANSACTION;
  UPDATE rkb2_ch2_source_review r
  JOIN sources s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CASE s.citation_number
      WHEN 86 THEN 'https://doi.org/10.1207/s15327809jls0202_2'
      WHEN 87 THEN 'https://doi.org/10.3102/0013189X032001005'
      WHEN 88 THEN 'https://doi.org/10.3102/0013189X032001009'
      WHEN 89 THEN 'https://doi.org/10.4324/9781315105642'
      WHEN 90 THEN 'https://www.ida.liu.se/~961G29/matr/didaktik/edr.pdf'
      WHEN 91 THEN 'https://research.tue.nl/en/publications/formative-evaluation-in-educational-design-research/'
      WHEN 92 THEN 'https://books.google.com/books?id=bhLLmgEACAAJ'
      WHEN 93 THEN 'https://ies.ed.gov/ncee/WWC/Docs/referenceresources/Final_WWC-HandbookVer5_0-0-508.pdf'
      WHEN 94 THEN 'https://www.sagepub.com/shop/buy-a-book/designing-and-conducting-mixed-methods-research-3-241842'
      WHEN 95 THEN 'https://www.sagepub.com/shop/buy-a-book/case-study-research-and-applications-6-250150'
      WHEN 96 THEN 'https://doi.org/10.1191/1478088706qp063oa'
      WHEN 97 THEN 'https://www.ets.org/research/policy_research_reports/publications/article/1995/buwh.html'
      WHEN 98 THEN 'https://ncme.org/resources/books/testing-standards/'
      WHEN 99 THEN 'https://doi.org/10.1037/h0026256'
      WHEN 100 THEN 'https://doi.org/10.1525/collabra.33267'
      WHEN 101 THEN 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5856500/'
      WHEN 102 THEN 'https://www.bera.ac.uk/publication/ethical%20guidelines-%20%20%20%20%20%20for-educational-research-2018'
      ELSE NULL END,
      r.edition_or_version=CASE s.citation_number
      WHEN 86 THEN 'Brown (1992), The Journal of the Learning Sciences 2(2), S. 141-178; Taylor & Francis, online 2009'
      WHEN 87 THEN 'Design-Based Research Collective (2003), Educational Researcher 32(1), S. 5-8'
      WHEN 88 THEN 'Cobb, Confrey, diSessa, Lehrer und Schauble (2003), Educational Researcher 32(1), S. 9-13'
      WHEN 89 THEN 'McKenney/Reeves, Conducting Educational Design Research, 2. Auflage, Routledge (2018)'
      WHEN 90 THEN 'Plomp (2013), Educational Design Research: An Introduction, in SLO Part A, 2013; Datenbank S. 11-50'
      WHEN 91 THEN 'Nieveen/Folmer (2013), in Plomp/Nieveen, Educational Design Research Part A, S. 152-169, Enschede SLO'
      WHEN 92 THEN 'Shadish, Cook und Campbell (2002), Experimental and Quasi-Experimental Designs for Generalized Causal Inference, Houghton Mifflin'
      WHEN 93 THEN 'What Works Clearinghouse Procedures and Standards Handbook, Version 5.0, August 2022, revidiert Dezember 2022'
      WHEN 94 THEN 'Creswell/Plano Clark, Designing and Conducting Mixed Methods Research, 3. Auflage, Datenbank 2018'
      WHEN 95 THEN 'Yin, Case Study Research and Applications: Design and Methods, 6. Auflage, Datenbank 2018'
      WHEN 96 THEN 'Braun/Clarke (2006), Qualitative Research in Psychology 3(2), S. 77-101'
      WHEN 97 THEN 'Messick (1995), American Psychologist 50(9), S. 741-749'
      WHEN 98 THEN 'AERA/APA/NCME (2014), Standards for Educational and Psychological Testing, gemeinsame Ausgabe'
      WHEN 99 THEN 'Cohen (1968), Psychological Bulletin 70(4), S. 213-220, Weighted Kappa'
      WHEN 100 THEN 'Lakens (2022), Collabra: Psychology 8(1), Article 33267'
      WHEN 101 THEN 'Nosek/Ebersole/DeHaven/Mellor (2018), PNAS 115(11), S. 2600-2606'
      WHEN 102 THEN 'British Educational Research Association (2018), Ethical Guidelines for Educational Research, 4. Ausgabe'
      ELSE NULL END,
      r.metadata_comparison=CASE s.citation_number
      WHEN 86 THEN 'Taylor & Francis bestaetigt Jahr 1992, Journal 2(2), Seiten 141-178 und DOI. 2009 ist nur das Online-Datum.'
      WHEN 87 THEN 'SAGE nennt den korporativen Autor und 2003, Heft 32(1), Seiten 5-8. Die Autorengruppe wird im Verlagsdokument aufgeschluesselt.'
      WHEN 88 THEN 'JSTOR-Heftverzeichnis verifiziert die fuenf Autoren, die Seiten 9-13 und direkte Nachbarschaft zu [87].'
      WHEN 89 THEN 'Forschungsportal Twente nennt 2nd edition, 3. September 2018, DOI und 326 Seiten.'
      WHEN 90 THEN 'Original-SLO-Buch (ISBN 9789032923341) bestaetigt den Autor und Sammelband. Seitenangaben 10-51 beziehungsweise 11-50 erscheinen in verschiedenen Nachweisen.'
      WHEN 91 THEN 'Universitaetsrepositorium verifiziert beide Autorinnen, Kapitel 6, 2013, SLO sowie Seiten 152-169.'
      WHEN 92 THEN 'Bibliografisch bestaetigt: 2002, drei Autoren, Verlag Houghton Mifflin, 623 Seiten. Detaillierte Originalseiten stehen noch aus.'
      WHEN 93 THEN 'IES bestaetigt Version 5.0 und die Dezemberrevision; aktualisierte Textstellen sind redaktionell, keine grundlegend neuen Standards.'
      WHEN 94 THEN 'SAGE-Verlagsseite fuehrt August 2017; akademische Bibliografien zitieren oft 2018. Beide Angaben vor finaler Normierung editionsbezogen klaeren.'
      WHEN 95 THEN 'SAGE fuehrt September 2017, WorldCat die gedruckte 6. Auflage 2018. Jahresabweichung ist vor finaler Editionsangabe aufzuklaeren.'
      WHEN 96 THEN 'Verlag belegt Druckjahr 2006, Heft, Seiten und DOI; Online-Datum 2008 ist kein alternatives Originalerscheinungsjahr.'
      WHEN 97 THEN 'ETS bestaetigt Samuel J. Messick, 1995, 50(9), S. 741-749; formale DOI-Datenbankreferenz im Text vorhanden.'
      WHEN 98 THEN 'Drei Fachgesellschaften sowie 2014-Ausgabe verifiziert; Volltext steht offiziell als Open Access bereit. Exakte Standardnummern im Manuskript noch nicht genannt.'
      WHEN 99 THEN 'PubMed bestaetigt DOI, Titel, Autor, Jahr, Heft und Seiten. Kein Originalabstract verfuegbar.'
      WHEN 100 THEN 'UC-Press Originalartikel bestaetigt Autor, 22. Maerz 2022, Band 8(1), Art. 33267 und DOI.'
      WHEN 101 THEN 'PubMed/PMC belegen vier Autoren, 2018, DOI 10.1073/pnas.1708274114 und 115(11), S. 2600-2606.'
      WHEN 102 THEN 'BERA bestaetigt 4. Ausgabe 2018 und die Veroeffentlichung am 20.06.2018.'
      ELSE NULL END
  WHERE s.citation_number BETWEEN 86 AND 102 AND r.review_status='open';
  IF ROW_COUNT() <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 SOURCE REVIEW COUNT FAIL';
  END IF;

  UPDATE rkb2_ch2_claim_review c
  JOIN source_usage u ON u.usage_id=c.usage_id
  JOIN dissertation_sections d ON d.section_id=u.section_id
  JOIN sources s ON s.source_id=u.source_id
  SET c.review_status='in_review',
      c.evidence_uri=CASE s.citation_number
      WHEN 86 THEN 'https://doi.org/10.1207/s15327809jls0202_2'
      WHEN 87 THEN 'https://doi.org/10.3102/0013189X032001005'
      WHEN 88 THEN 'https://doi.org/10.3102/0013189X032001009'
      WHEN 89 THEN 'https://doi.org/10.4324/9781315105642'
      WHEN 90 THEN 'https://www.ida.liu.se/~961G29/matr/didaktik/edr.pdf'
      WHEN 91 THEN 'https://research.tue.nl/en/publications/formative-evaluation-in-educational-design-research/'
      WHEN 92 THEN 'https://books.google.com/books?id=bhLLmgEACAAJ'
      WHEN 93 THEN 'https://ies.ed.gov/ncee/WWC/Docs/referenceresources/Final_WWC-HandbookVer5_0-0-508.pdf'
      WHEN 94 THEN 'https://www.sagepub.com/shop/buy-a-book/designing-and-conducting-mixed-methods-research-3-241842'
      WHEN 95 THEN 'https://www.sagepub.com/shop/buy-a-book/case-study-research-and-applications-6-250150'
      WHEN 96 THEN 'https://doi.org/10.1191/1478088706qp063oa'
      WHEN 97 THEN 'https://www.ets.org/research/policy_research_reports/publications/article/1995/buwh.html'
      WHEN 98 THEN 'https://ncme.org/resources/books/testing-standards/'
      WHEN 99 THEN 'https://doi.org/10.1037/h0026256'
      WHEN 100 THEN 'https://doi.org/10.1525/collabra.33267'
      WHEN 101 THEN 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5856500/'
      WHEN 102 THEN 'https://www.bera.ac.uk/publication/ethical%20guidelines-%20%20%20%20%20%20for-educational-research-2018'
      ELSE NULL END,
      c.edition_or_version=CASE s.citation_number
      WHEN 86 THEN 'Brown (1992), The Journal of the Learning Sciences 2(2), S. 141-178; Taylor & Francis, online 2009'
      WHEN 87 THEN 'Design-Based Research Collective (2003), Educational Researcher 32(1), S. 5-8'
      WHEN 88 THEN 'Cobb, Confrey, diSessa, Lehrer und Schauble (2003), Educational Researcher 32(1), S. 9-13'
      WHEN 89 THEN 'McKenney/Reeves, Conducting Educational Design Research, 2. Auflage, Routledge (2018)'
      WHEN 90 THEN 'Plomp (2013), Educational Design Research: An Introduction, in SLO Part A, 2013; Datenbank S. 11-50'
      WHEN 91 THEN 'Nieveen/Folmer (2013), in Plomp/Nieveen, Educational Design Research Part A, S. 152-169, Enschede SLO'
      WHEN 92 THEN 'Shadish, Cook und Campbell (2002), Experimental and Quasi-Experimental Designs for Generalized Causal Inference, Houghton Mifflin'
      WHEN 93 THEN 'What Works Clearinghouse Procedures and Standards Handbook, Version 5.0, August 2022, revidiert Dezember 2022'
      WHEN 94 THEN 'Creswell/Plano Clark, Designing and Conducting Mixed Methods Research, 3. Auflage, Datenbank 2018'
      WHEN 95 THEN 'Yin, Case Study Research and Applications: Design and Methods, 6. Auflage, Datenbank 2018'
      WHEN 96 THEN 'Braun/Clarke (2006), Qualitative Research in Psychology 3(2), S. 77-101'
      WHEN 97 THEN 'Messick (1995), American Psychologist 50(9), S. 741-749'
      WHEN 98 THEN 'AERA/APA/NCME (2014), Standards for Educational and Psychological Testing, gemeinsame Ausgabe'
      WHEN 99 THEN 'Cohen (1968), Psychological Bulletin 70(4), S. 213-220, Weighted Kappa'
      WHEN 100 THEN 'Lakens (2022), Collabra: Psychology 8(1), Article 33267'
      WHEN 101 THEN 'Nosek/Ebersole/DeHaven/Mellor (2018), PNAS 115(11), S. 2600-2606'
      WHEN 102 THEN 'British Educational Research Association (2018), Ethical Guidelines for Educational Research, 4. Ausgabe'
      ELSE NULL END,
      c.page_or_section=CASE s.citation_number
      WHEN 86 THEN 'Verlagsseite, Abstract; Originalartikel: Volltextabschnitte vor finaler Abzeichnung abgleichen'
      WHEN 87 THEN 'SAGE Originalartikel/Autorengruppe; Zeitschriftenheft 32(1); Konzept und Zusammenfassung'
      WHEN 88 THEN 'JSTOR/SAGE Verlagsdaten; Originalartikel zu Designexperimenten; Detailbelege vor finaler Abzeichnung'
      WHEN 89 THEN 'University of Twente, Buchmetadaten; Routledge Originalausgabe; Inhaltsverzeichnis zur Methodik'
      WHEN 90 THEN 'SLO Part-A-Originalpublikation, Inhalt und Kapitel 1; Anfangs- und Endseite der Druckfassung final pruefen'
      WHEN 91 THEN 'Eindhoven University of Technology: Kapitel 6, Seiten 152-169; Part-A-Original-PDF Kapitel 6'
      WHEN 92 THEN 'Verlagsbibliografie/Google Books: Inhaltskapitel zu interner, externer und statistischer Validitaet sowie quasi-experimentellen Designs'
      WHEN 93 THEN 'Offizielles IES-Original-PDF: Titelseite, Chapter III zu RCT/Quasi-Experimenten; Baseline/Attrition/Outcome-Standards'
      WHEN 94 THEN 'SAGE Originalverlag: Ausgabe, Inhaltsverzeichnis, Mixed-Methods-Designs; Copyright-/Erscheinungsjahr vor FINAL pruefen'
      WHEN 95 THEN 'SAGE Originalverlag: Inhaltsverzeichnis und Fallstudienansatz; WorldCat 2018; Impressum abgleichen'
      WHEN 96 THEN 'Taylor & Francis Originalabstract: thematische Analyse, epistemologische Positionen, Transparenz, Stolpersteine'
      WHEN 97 THEN 'ETS-Autoren-/Forschungsdatensatz und ERIC Abstract: Testwertinterpretationen und Validitaetsargumentation'
      WHEN 98 THEN 'Offizielle NCME-/APA-Seiten zur 2014-Ausgabe, Validitaet, Fairness, Testentwicklung und Anwendung'
      WHEN 99 THEN 'PubMed Originalbibliografie: Oct 1968, 70(4), S. 213-220; Originalvolltext fuer Formeln vor FINAL erforderlich'
      WHEN 100 THEN 'Offene Originalveroeffentlichung: Abstract; Six Approaches to Justify Sample Sizes; Discussion'
      WHEN 101 THEN 'PMC-Volltext: Abstract, Differenzierung prediction/postdiction, preregistered confirmatory vs exploratory research'
      WHEN 102 THEN 'Offizielle BERA-Seite, Ausgabe Juni 2018; Onlineleitfaden zu Einwilligung, Freiwilligkeit, Datenschutz und Forschungsverantwortung'
      ELSE NULL END,
      c.assessment=CASE s.citation_number
      WHEN 86 THEN 'Browns Entwurf von Designexperimenten im realen Unterricht sowie die Verbindung von Gestaltung und Forschung sind im Originalabstract nachvollziehbar. Keine FRZK-Studie.'
      WHEN 87 THEN 'Didaktische Gestaltung, theoriebildende Forschung und kontextgebundene Erklaerungen sind im Originaltext angelegt. Kein experimenteller Wirksamkeitsnachweis fuer das FRZK.'
      WHEN 88 THEN 'Iterative Entwicklung, Analyse von Lernverlaeufen und bereichsspezifische Theorieansprueche passen zum Beitrag. Praezise Retrospektiv-Analyse noch durch Volltextstellen belegen.'
      WHEN 89 THEN 'Entwicklungsforschung verbindet Problem-/Praxisanalyse, Entwicklung, Evaluation und theoretische Reflexion. Kapitelgenaue Aussagen noch anhand Buchseiten kontrollieren.'
      WHEN 90 THEN 'Problemorientierte Entwicklungsforschung, Voruntersuchung, Prototyping, formative und summative Schritte sind im Werk dargestellt; Seitenzaehlung vor finaler Zitierfassung abgleichen.'
      WHEN 91 THEN 'Relevanz, Konsistenz, praktische Einsetzbarkeit und Wirksamkeit sind getrennte Qualitaetskriterien. Erwartete und tatsaechliche Wirksamkeit duerfen nicht gleichgesetzt werden.'
      WHEN 92 THEN 'Kontroll- und Vergleichsgruppen, alternative Ursachen, Validitaet und Generalisierung sind zentrale Inhalte. Unterrichten mit FRZK ist in dem Buch nicht empirisch untersucht.'
      WHEN 93 THEN 'Methodische Anforderungen an kausale Interventionsstudien sind primaerbelegt. Nicht als Nachweis eigener FRZK-Wirksamkeit verwenden.'
      WHEN 94 THEN 'Integration qualitativer und quantitativer Analyse ist Kerngegenstand; nur parallele Datenerhebung ohne Integration genuegt dem Designanspruch nicht.'
      WHEN 95 THEN 'Fallabgrenzung, Fallstudienplanung, alternative Erklaerungen und mehrere Datenquellen sind thematisch einschlaegig. Keine unmittelbare Kausalwirkung des FRZK daraus ableiten.'
      WHEN 96 THEN 'Themenidentifikation und theoretisch reflektierte qualitative Auswertung sind explizit beschrieben; keine generelle statistische Objektivitaet einer Themenkodierung postulieren.'
      WHEN 97 THEN 'Interpretation und Verwendung von Testergebnissen benoetigen zweckbezogene Evidenz; Reliabilitaet allein beweist nicht die beabsichtigte Interpretation.'
      WHEN 98 THEN 'Validitaet, Messqualitaet und Fairness sind zentral. Die Standards garantieren nicht die Eignung eines neu entwickelten FRZK-Ratings ohne eigene Validierungsstudie.'
      WHEN 99 THEN 'Gewichtetes Kappa beruecksichtigt abgestufte Unstimmigkeiten zwischen Ratern; fuer ordinale FRZK-Rubriken grundsaetzlich geeignet, aber noch keine berechnete Uebereinstimmung vorhanden.'
      WHEN 100 THEN 'Stichprobengroesse ist auf Inferenzziel, Praezision, Power und Ressourcen zu beziehen. Keine pauschale Mindestgroesse ableitbar.'
      WHEN 101 THEN 'Praeregistrierung soll Hypothesenpruefung und nachtraegliche Exploration transparent trennen, Exploration aber nicht verbieten.'
      WHEN 102 THEN 'Einwilligung und besonderer Schutz von Lernenden sind einschlaegig; FRZK-Forschung erfordert konkrete Datenschutz-, Freiwilligkeits- und Machtasymmetrieprotokolle.'
      ELSE NULL END
  WHERE d.section_code='2.6' AND s.citation_number BETWEEN 86 AND 102 AND c.review_status='open';
  IF ROW_COUNT() <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 CLAIM REVIEW COUNT FAIL';
  END IF;
  SELECT COUNT(*) INTO v_sources FROM rkb2_ch2_source_review r
     JOIN sources s ON s.source_id=r.source_id
     WHERE s.citation_number BETWEEN 86 AND 102 AND r.review_status='in_review'
     AND r.evidence_uri IS NOT NULL AND r.edition_or_version IS NOT NULL
     AND r.metadata_comparison IS NOT NULL AND r.reviewer IS NULL AND r.reviewed_at IS NULL;
  SELECT COUNT(*) INTO v_claims FROM rkb2_ch2_claim_review c
     JOIN source_usage u ON u.usage_id=c.usage_id
     JOIN dissertation_sections d ON d.section_id=u.section_id
     JOIN sources s ON s.source_id=u.source_id
     WHERE d.section_code='2.6' AND s.citation_number BETWEEN 86 AND 102 AND c.review_status='in_review'
     AND c.evidence_uri IS NOT NULL AND c.edition_or_version IS NOT NULL AND c.page_or_section IS NOT NULL
     AND c.assessment IS NOT NULL AND c.reviewer IS NULL AND c.reviewed_at IS NULL;
  IF v_sources <> 17 OR v_claims <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.6 AUDIT POSTSTATE FAIL';
  END IF;
  COMMIT;
  SELECT 'SECTION_26_EVIDENCE_PRESTAGED' AS check_code,'PASS' AS result,
      v_sources AS sources_in_review,v_claims AS claims_in_review,
      'Preliminary only. Chapter 2 remains DRAFT; GATE_05 remains BLOCKED.' AS note;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_ch2_precheck_27` ()   BEGIN
  DECLARE v_sources INT DEFAULT 0;
  DECLARE v_claims INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF (SELECT COUNT(*) FROM rkb2_ch2_source_review) <> 135 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review) <> 141 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 AUDIT REGISTER SIZE FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='in_review') <> 88 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='open') <> 53 OR
     (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE review_status='supported') <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 PRIOR AUDIT STATE FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review WHERE section_code='2.7' AND review_status='open') <> 17 OR
     (SELECT COUNT(*) FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
       WHERE s.citation_number BETWEEN 103 AND 119 AND r.review_status='open') <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 TARGET REVIEWS NOT OPEN';
  END IF;
  IF (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
      JOIN sources s ON s.source_id=u.source_id JOIN rkb2_ch2_claim_review c ON c.usage_id=u.usage_id
      JOIN rkb2_ch2_source_review r ON r.source_id=s.source_id
      WHERE d.section_code='2.7' AND s.citation_number BETWEEN 103 AND 119) <> 17 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 USAGE REGISTRY NOT EXACT 17';
  END IF;
  IF (SELECT COUNT(*) FROM section_change_log l JOIN dissertation_sections d ON d.section_id=l.section_id
      WHERE d.section_code='2.7' AND l.object_type='manuscript'
      AND BINARY SHA2(l.new_value,256)=BINARY 'cabf32528857bbb4648529ec95ab6623490ad158cc1ae2176912606e6f82fcd0') <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 IMPORT TEXT SHA256 FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_source_review r JOIN sources s ON s.source_id=r.source_id
      WHERE s.citation_number BETWEEN 103 AND 119 AND (r.review_status <> 'open'
      OR r.reviewer IS NOT NULL OR r.reviewed_at IS NOT NULL
      OR BINARY r.source_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),s.source_key,s.full_citation_text,
         COALESCE(s.doi,''),COALESCE(s.year_edition,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 SOURCE AUDIT FINGERPRINT FAIL';
  END IF;
  IF EXISTS (SELECT 1 FROM rkb2_ch2_claim_review c JOIN source_usage u ON u.usage_id=c.usage_id
      JOIN dissertation_sections d ON d.section_id=u.section_id JOIN sources s ON s.source_id=u.source_id
      WHERE d.section_code='2.7' AND s.citation_number BETWEEN 103 AND 119
      AND (c.review_status <> 'open' OR c.reviewer IS NOT NULL OR c.reviewed_at IS NOT NULL
      OR BINARY c.claim_fingerprint <> BINARY SHA2(CONCAT_WS(CHAR(31),COALESCE(u.claim_summary,''),
         COALESCE(u.exact_location,''),COALESCE(u.notes,'')),256))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 CLAIM AUDIT FINGERPRINT FAIL';
  END IF;
  IF (SELECT COUNT(*) FROM dissertation_sections WHERE chapter_no=2 AND status='draft') <> 12 OR
     (SELECT COUNT(*) FROM source_usage u JOIN dissertation_sections d ON d.section_id=u.section_id
      WHERE d.chapter_no=2 AND d.section_code LIKE '2.%' AND u.citation_checked=1) <> 0 OR
     (SELECT COUNT(*) FROM sources WHERE citation_number BETWEEN 15 AND 149 AND verification_status='verified') <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 SCIENTIFIC GATE STATE CHANGED';
  END IF;
  IF (SELECT COUNT(*) FROM rkb2_ch2_claim_review
      WHERE section_code IN ('2.0','2.1','2.2','2.3','2.4','2.5','2.6') AND review_status='in_review') <> 88 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='2.7 PREVIOUS SECTIONS NOT COMPLETE';
  END IF;

  START TRANSACTION;
  UPDATE rkb2_ch2_source_review r
  JOIN sources s ON s.source_id=r.source_id
  SET r.review_status='in_review',
      r.evidence_uri=CASE s.citation_number
