      WHEN 104 THEN 'https://direct.mit.edu/books/oa-monograph/4581/Cybernetics-or-Control-and-Communication-in-the'
      WHEN 105 THEN 'https://www.ashby.info/bibliography.html'
      WHEN 106 THEN 'https://doi.org/10.1002/j.1538-7305.1948.tb01338.x'
      WHEN 107 THEN 'https://books.google.com/books/about/Industrial_Dynamics.html?id=4CgzAAAAMAAJ'
