      WHEN 113 THEN 'https://www.routledge.com/RADICAL-CONSTRUCTIVISM/Glasersfeld/p/book/9780750703871'
      WHEN 114 THEN 'https://openlibrary.org/books/OL5512778M/Laws_of_form'
      WHEN 115 THEN 'https://www.cambridge.org/core/books/causality/B0046844FAE10CBF274D4ACBDAEB5F5B'
      WHEN 116 THEN 'https://doi.org/10.1093/0198247044.001.0001'
      WHEN 117 THEN 'https://press.uchicago.edu/ucp/books/book/chicago/E/bo3622319.html'
      WHEN 118 THEN 'https://doi.org/10.1080/01621459.1976.10480949'
      WHEN 119 THEN 'https://doi.org/10.1017/CBO9780511814563'
      ELSE NULL END,
