CREATE DEFINER=`root`@`localhost` PROCEDURE `rkb2_recover_source_snapshots_20261021` ()   BEGIN
  DECLARE v_count INT DEFAULT 0;
  DECLARE v_missing INT DEFAULT 0;
  DECLARE v_wrong INT DEFAULT 0;
  DECLARE v_mismatch INT DEFAULT 0;

  DROP TEMPORARY TABLE IF EXISTS `tmp_rkb2_recovery_sources`;
  CREATE TEMPORARY TABLE `tmp_rkb2_recovery_sources` (
    section_code varchar(50) NOT NULL PRIMARY KEY,
    section_id bigint unsigned NOT NULL,
    heading varchar(500) NOT NULL,
    change_id bigint unsigned NOT NULL,
    body_text longtext NOT NULL,
    body_sha256 char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

  -- Neuesten LANGEN Manuskriptimport je Sollabschnitt waehlen; kurze Statuswechsel ausschliessen.
  -- Fuer einen Abschnitt mit mehreren langen Importen ist dies der NEUESTE, nicht zwingend
  -- die vom Autor freigegebene Importrevision: deshalb Provenienzpruefung vor RELEASE.
  INSERT INTO `tmp_rkb2_recovery_sources`
     (section_code,section_id,heading,change_id,body_text,body_sha256)
  SELECT s.section_code,s.section_id,s.title,c.change_id,c.new_value,
         SHA2(c.new_value,256)
  FROM `dissertation_sections` s
  JOIN `section_change_log` c ON c.change_id = (
     SELECT MAX(x.change_id)
     FROM `section_change_log` x
     WHERE x.object_reference=s.section_code
       AND CHAR_LENGTH(x.new_value)>=1000
       AND x.new_value LIKE CONCAT('# ',s.section_code,' %')
  )
  WHERE s.section_code REGEXP '^2\\.(0|[1-9]|10)$';

  SELECT COUNT(*) INTO v_count FROM `tmp_rkb2_recovery_sources`;
  IF v_count<>11 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ABBRUCH: Nicht exakt elf passende lange Original-Importtexte gefunden. Keine Snapshots angelegt.';
  END IF;

  START TRANSACTION;
  INSERT INTO `rkb2_ch2_section_snapshots`
    (section_id,section_code,heading,body_text,body_sha256,provenance)
  SELECT t.section_id,t.section_code,t.heading,t.body_text,t.body_sha256,
         CONCAT('original:section_change_log:change_id=',t.change_id)
  FROM `tmp_rkb2_recovery_sources` t
  WHERE NOT EXISTS (
    SELECT 1 FROM `rkb2_ch2_section_snapshots` ss
    WHERE ss.section_code=t.section_code
      AND BINARY ss.body_sha256=BINARY t.body_sha256
  );

  -- Integritaet von Quelle und Sicherung muss fuer jeden Abschnitt passen.
  SELECT COUNT(*) INTO v_mismatch
  FROM `tmp_rkb2_recovery_sources` t
  WHERE NOT EXISTS (
    SELECT 1 FROM `rkb2_ch2_section_snapshots` ss
    WHERE ss.section_code=t.section_code
      AND BINARY ss.body_sha256=BINARY SHA2(ss.body_text,256)
      AND BINARY ss.body_sha256=BINARY t.body_sha256
      AND BINARY ss.body_text=BINARY t.body_text
  );
  IF v_mismatch<>0 THEN
    ROLLBACK;
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ABBRUCH/ROLLBACK: Originaltext, Snapshot oder SHA-256 nicht identisch.';
  END IF;
  COMMIT;
END$$

