  IF NOT ((SELECT COUNT(*) FROM dissertation_sections WHERE section_code='3.8' AND status='draft')=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RKB38 PRESTATE FAIL: CHAPTER_38'; END IF;
