                MESSAGE_TEXT='RKB33-N69 RECOVERY-GATE: N6.9 existiert, aber ein gültiges RKB33-N6-FINAL-GATE fehlt.';
        END IF;

        SET v_recovery=1;
        SET v_n6_ok=1;
    ELSEIF (SELECT COUNT(*) FROM appendix_sections
