(3, '1.3', 2, 'Mächtigkeit der leeren Menge', '\\left|\\varnothing\\right|=0', '\\left|\\varnothing\\right|=0', 'Die leere Menge besitzt genau null Elemente', 'definition', 'literature', NULL, 'Im DOCX als Word-Formel mit zugehöriger Word-LaTeX-Zeile hinterlegt.', 'Kardinalität des leeren Mengenobjekts.', 'verified', 2),
(4, '1.4', 2, 'FRZK-Initialisierung', 'T(\\varnothing)=I', 'T(\\varnothing)=I', 'Die modellinterne Zuordnung T verbindet den leeren Ausgangszustand mit dem Initialpunkt I', 'definition', 'original', NULL, 'Im DOCX als Word-Formel mit zugehöriger Word-LaTeX-Zeile hinterlegt.', 'Definitionsbereich, Zielbereich und Art der Zuordnung noch festzulegen.', 'draft', 2),
(5, '1.5', 24, 'Symbolisches Rückbezugsschema', 'f_n(I)=f_{n-1}(I)\\oplus f_n(I)', 'f_n(I)=f_{n-1}(I)\\oplus f_n(I)', 'Symbolische Form, keine geschlossene Rekursion ohne Definition des Operators ⊕', 'schema', 'original', NULL, 'Im DOCX als Word-Formel mit zugehöriger Word-LaTeX-Zeile hinterlegt.', 'f_n steht auf beiden Seiten; nicht als mathematischer Beweis interpretieren.', 'draft', 2);

