INSERT INTO `repository_revisions` (`revision_id`, `revision_code`, `revision_date`, `scope_type`, `scope_reference`, `version_label`, `summary`, `created_by`, `parent_revision_id`) VALUES
(2, 'RKB1-REV-CH1-2026-10-17', '2026-10-17 14:39:37', 'chapter', '1', 'CH1-import-v1', 'Kapitel-1-Import: Literaturliste 1-14, 18 Quellenverwendungen, 5 Gleichungen, Definitionen, Symbole, Figuren und Provenienz. Wissenschaftliche Final-Freigabe bleibt offen.', 'Olaf Thiele / ChatGPT', NULL),
(3, 'RKB1-REV-CH1-LITDEEP-2026-10-17', '2026-10-17 15:26:17', 'chapter', '1', 'CH1-deep-research-evidence-v1', '14 quellenbezogene sinngemaesse Belege; drei direkt gepruefte Kurzoriginalzitate; ein unbestaetigtes Transkript und eine sekundar berichtete Originalaussage, ohne Finalfreigabe.', 'Olaf Thiele / ChatGPT', 2),
(4, 'RKB1-REV-CH1-CONSISTENCY-2026-10-17', '2026-10-17 15:43:40', 'chapter', '1', 'chapter1-consistency-review-v1', 'Wissenschaftliche Konsistenzpruefung Kapitel 1, Stand 2026-10-17. Original SHA256 83e27ffd3d0bcde448112dc0643d72fd13070303e734660fc4c294354559e05b; redigierte Arbeitsfassung SHA256 78e3096d469a25f94540143bbe86ee3715e1465beebaa3b48cce742a073b489a. Keine automatisch freigegebene fachliche Aussage.', 'FRZK / redaktionelle Auditpruefung', 3),
(6, 'RKB1-REV-CH1-INTRO-2026-10-17', '2026-10-17 17:08:34', 'chapter', '1', 'ch1-introduction-without-equations-v1', 'Kapitel 1 als didaktisch-methodische Einleitung: 23 aktive Abschnitte, 14 Quellen, 18 Belegstellen, 3 unveraenderte Abbildungen, 0 aktive Gleichungen und 0 aktive Formaldefinitionen. Historischer Bestand unveraendert, Fachfreigabe offen.', 'FRZK / redaktionelle Revision', 4),
(7, 'RKB1-REV-CH1-LITERATURE-DESIGN-2026-10-17', '2026-10-17 17:36:29', 'chapter', '1', 'lit-design-review-v1', 'Literatur-Aussagepassung ohne erfundene Seitenbelege; Forschungsprotokoll geplant; neuer DOCX-Textsnapshot; keine wissenschaftliche Gesamtfreigabe.', 'Olaf Thiele / ChatGPT', 6),
(8, 'RKB1-REV-CH1-MANUSCRIPT-2026-10-17', '2026-10-17 17:55:44', 'chapter', '1', 'manuscript-editorial-v1', 'Redaktioneller Manuskriptabschluss: problematische Patent-/ICAS-Angaben sowie unsichere Taschner-Abbildung ausgeschlossen, Quellen und Forschungsplan nicht final empirisch verifiziert.', 'ChatGPT', 7),
(9, 'RKB1-REV-CH1-FIRST-CITATION-2026-10-17', '2026-10-19 06:30:29', 'chapter', '1', 'chapter-1-first-citation-order-v1', 'Die 14 Literaturpositionen werden nach Erstnennung in Kapitel 1 neu nummeriert. Alte source_id und historische Quellen- und Zitierrevisionen bleiben unveraendert. Kapitel weiterhin zur Autorenpruefung, keine wissenschaftliche Gesamtfreigabe.', 'FRZK / redaktionelle Revision', 8),
(10, 'RKB1-REV-CH1-EXTERNAL-DOCX-2026-10-19', '2026-10-19 06:50:30', 'chapter', '1', 'external-docx-evidence-v1', 'Autor meldet am 2026-10-19 eine lokale PowerShell SHA256-Pruefung der neuesten Kapitel-1-DOCX. Ermittelter Hash stimmt mit dem vorhandenen revisionsgebundenen Snapshot ueberein. Autorenfreigabe, Literaturinhalte und Abbildungsprovenienz offen; kein RELEASED.', 'FRZK / Autorennachweis und Datenbankpruefung', 9),
(11, 'RKB1-REV-CH1-AUTHOR-APPROVAL-2026-10-19', '2026-10-19 07:13:08', 'chapter', '1', 'author-literature-approval-v1', 'Autorenentscheidung vom 19.10.2026: Literatur PASS; Kapitel 1 zur Freigabe autorisiert. Originalseitenverifikation nicht pauschal behauptet. Figur- und Metadaten-Nachweise bleiben bis Dokumentation OPEN.', 'Autor (im Chat erklaerte Freigabe)', 10),
(12, 'RKB1-REV-CH1-PROVENANCE-2026-10-19', '2026-10-19 07:29:00', 'chapter', '1', 'author-provenance-evidence-v1', 'Zwei Abbildungsnachweise und Quellenmetadatenkontrolle vom Autor konkret nachgewiesen; Daten als AUTHOR_REPORTED, nicht als unabhaengige Drittpruefung gekennzeichnet.', 'Autor / beleggestuetzte Freigabevorbereitung', 11),
(13, 'RKB1-REV-CH1-RELEASED-2026-10-19', '2026-10-19 07:30:00', 'chapter', '1', 'released-author-approved-v1', 'Kapitel 1 vom Autor freigegeben auf Basis SHA256-verknuepfter Manuskriptrevision; Literatur 18/18 AUTHOR_CONTENT_PASS; Abbildungsrechte und Metadaten AUTHOR_REPORTED. Dies ist keine Behauptung externer Peer-Review.', 'Autor / Kapitel-1-Freigabe', 12),
(14, 'RKB2-REV-CH2-20-DRAFT-2026-10-19', '2026-10-19 08:30:24', 'chapter', '2', '2.0-draft-v1', 'Fachgliederung 2.0-2.10 und vollständiger erster Textentwurf 2.0 mit vier vorläufig nummerierten methodischen Quellen. Wissenschaftliche Originalstellenprüfung und Autorenfreigabe OPEN.', 'Olaf Thiele / ChatGPT', 13),
(15, 'RKB2-REV-CH2-21-DRAFT-2026-10-19', '2026-10-19 09:16:32', 'section', '2.1', '2.1-draft-symbolic-orientation-v1', 'Konsolidierter Entwurf: funktionale Modellierung; FRZK-Regeln fuer +/–Unendlich, +/–0, Orientierungserhalt bei Skalarmultiplikation mit 0. Keine mathematische oder empirische Freigabe.', 'Olaf Thiele / ChatGPT', 14),
(16, 'RKB2-REV-CH2-AUTHORS-15-31-2026-10-19', '2026-10-19 09:40:32', 'source', '15-31', 'ch2-authors-correction-v1', 'Autorenstammdaten und geordnete Quellenzuordnungen fuer Kapitel 2.0-2.1 nachmaterialisiert. Keine Kapitel-1-Aenderung und keine wissenschaftliche Gesamtfreigabe.', 'FRZK / bibliografische Korrektur', 15),
(17, 'RKB2-REV-CH2-22-DRAFT-2026-10-19', '2026-10-19 09:57:47', 'section', '2.2', '2.2-draft-representations-v1', 'Vollstaendiger Abschnitt 2.2 zu Repraesentationen, Concept-Maps, FRZK-Symbolik und Orientierungserhalt; zehn neue Quellen und Autorenrelationen. Wissenschaftliche Belege offen.', 'Olaf Thiele / ChatGPT', 16),
(18, 'RKB2-REV-CH2-23-DRAFT-2026-10-19', '2026-10-19 13:15:43', 'section', '2.3', '2.3-draft-problem-solving-v1', 'Kapitel 2.3: Aufgabenverstaendnis, Problemloesen, Transfer; vier FRZK-Symbole, Orientierungsinformation; Literatur 42-55, Autoren und wissenschaftliche OPEN-Gates.', 'Olaf Thiele / ChatGPT', 17),
(20, 'RKB2-REV-CH2-24-DRAFT-2026-10-19', '2026-10-19 18:10:31', 'section', '2.4', '2.4-draft-prior-knowledge-v1', 'Kapitel 2.4: Vorwissen, Begriffsbildung und mathematische Kommunikation; Literatur 56-69; alle Autorenzuordnungen; wissenschaftliche OPEN-Gates.', 'Olaf Thiele / ChatGPT', 18),
(21, 'RKB2-REV-CH2-25-DRAFT-2026-10-19', '2026-10-19 18:43:37', 'section', '2.5', '2.5-draft-individual-support-v1', 'Abschnitt 2.5: Lernfoerderung, Scaffolding und Feedback; Literatur [70]-[85]; Autorenzuordnungen; wissenschaftliche Gates OPEN.', 'Olaf Thiele / ChatGPT', 20),
(22, 'RKB2-REV-CH2-26-DRAFT-2026-10-19', '2026-10-19 19:43:26', 'section', '2.6', '2.6-draft-evaluation-v1', 'Abschnitt 2.6 Didaktische Entwicklungsforschung und empirische Evaluation; Quellen [86]-[102]; wissenschaftliche Gates OPEN.', 'Olaf Thiele / ChatGPT', 21),
(23, 'RKB2-REV-CH2-27-DRAFT-2026-10-19', '2026-10-19 20:13:11', 'section', '2.7', '2.7-draft-systems-v1', 'Abschnitt 2.7 Systemtheorie, Kybernetik, Erkenntnistheorie; [103]-[119]; Gates OPEN.', 'Olaf Thiele / ChatGPT', 22),
(24, 'RKB2-REV-CH2-28-DRAFT-2026-10-20', '2026-10-20 08:26:49', 'section', '2.8', '2.8-draft-physical-models-v1', 'Abschnitt 2.8 Raum, Zeit und Beobachtung; [120]-[134]; wissenschaftliche Gates OPEN.', 'Olaf Thiele / ChatGPT', 23),
(26, 'RKB2-REV-CH2-29-DRAFT-2026-10-20', '2026-10-20 09:21:12', 'section', '2.9', '2.9-draft-critical-comparison-v1', 'Abschnitt 2.9 Kritische Gegenueberstellung; sieben neue Quellen [135]-[141], sechs bereits registrierte Werke wiederverwendet; wissenschaftliche Gates OPEN.', 'Olaf Thiele / ChatGPT', 24),
(28, 'RKB2-REV-CH2-210-DRAFT-2026-10-20', '2026-10-20 10:03:37', 'section', '2.10', '2.10-draft-import-v1', 'Acht neue Quellen [142]-[149]; Text nur redaktionelle Importfassung, Chat-Wortgleichheit OFFEN; kein FINAL.', 'FRZK / Redaktion', 26),
(29, 'RKB2-REV-CH2-REVIEW-2026-10-20', '2026-10-20 10:05:48', 'chapter', '2', 'ch2-review-open-v1', '17 wissenschaftliche Freigaben OPEN. Keine automatische Bestaetigung.', 'FRZK / Review-Plan', 28),
(30, 'RKB2-REV-CH2-AUTHOR-TEXT-A-2026-10-20', '2026-10-21 08:17:58', 'chapter', '2', 'ch2-canonical-imports-author-A-v1', 'Autorenentscheidung A: Alle 11 gespeicherten Importfassungen sind kanonischer Dissertationstext; keine Behauptung der Wortgleichheit frueherer Chat-Langfassungen.', 'FRZK / Autorenentscheidung im Chat', 29);

