--

CREATE TABLE `rkb1_research_protocol` (
  `protocol_item_id` bigint(20) UNSIGNED NOT NULL,
  `revision_id` bigint(20) UNSIGNED NOT NULL,
  `protocol_code` varchar(80) NOT NULL,
  `title` varchar(255) NOT NULL,
  `protocol_description` text NOT NULL,
  `implementation_state` varchar(40) NOT NULL DEFAULT 'planned',
  `evidence_of_execution` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Daten für Tabelle `rkb1_research_protocol`
--

INSERT INTO `rkb1_research_protocol` (`protocol_item_id`, `revision_id`, `protocol_code`, `title`, `protocol_description`, `implementation_state`, `evidence_of_execution`) VALUES
(1, 7, 'POP', 'Stichprobe', 'Gelegenheitsstichprobe, Ziel ca. 25 Lernende; Alter/Schulart/Stoffgebiet und Ein-/Ausschlusskriterien vorab festlegen.', 'planned', NULL),
(2, 7, 'COND', 'Vergleichsbedingungen', 'Konventionell angeleitete Bearbeitung gegen FRZK-orientierte Darstellung; Zeit, Hilfe und Bearbeitungsregeln gleich halten.', 'planned', NULL),
(3, 7, 'TASK', 'Aufgabenpaare', 'Fachlich gleichwertige Paare und Transferaufgaben; Pilotpruefung vor Forschungsbeginn.', 'planned', NULL),
(4, 7, 'ORDER', 'Reihenfolge', 'Aufgabenreihenfolge ausbalancieren und dokumentieren; keine Randomisierung behaupten, wenn nicht durchgefuehrt.', 'planned', NULL),
(5, 7, 'PRIMARY', 'Primaere Messgroesse', 'Fachlich nachvollziehbarer Loesungsweg mittels vier Kriterien 0..3; Gesamt 0..12; Rubrik vor Datenerhebung erproben.', 'planned', NULL),
(6, 7, 'SECONDARY', 'Sekundaere Messgroessen', 'Fehlerzahl und -art, Bearbeitungszeit, Tutorhilfen, Transferaufgabe und fehlende Werte dokumentieren.', 'planned', NULL),
(7, 7, 'CODING', 'Kodierqualitaet', 'Teilmenge pseudonymisierter Aufgaben von zweiter Person kodieren; Abweichungen protokollieren.', 'planned', NULL),
(8, 7, 'ANALYSIS', 'Auswertung', 'Zunaechst deskriptiv, Stichprobengrundlage und Streuung offenlegen; gepaarte Vergleiche nur falls Messanlage dies gestattet.', 'planned', NULL),
(9, 7, 'THREATS', 'Stoerfaktoren', 'Uebung, Tutorwirkung, Aufgabenvariation, Alter, Vorwissen, Reihenfolge sowie Selektionsverzerrung adressieren.', 'planned', NULL),
(10, 7, 'ETHICS', 'Ethik und Datenschutz', 'Freiwillige Teilnahme, Sorgeberechtigte bei Minderjaehrigen, Pseudonymisierung, Datensparsamkeit, Aufbewahrung und Rollenabgrenzung vorab klaeren.', 'planned', NULL),
(11, 7, 'DECISION', 'Geltungsgrenzen', 'Null- und Negativbefunde sowie nicht erreichte Teilziele dokumentieren; keine universelle Kausalwirkung bei n≈25 behaupten.', 'planned', NULL);

