INSERT INTO `rkb1_study_rubric` (`rubric_id`, `revision_id`, `rubric_code`, `criterion`, `score_min`, `score_max`, `score_0`, `score_1`, `score_2`, `score_3`, `rubric_state`) VALUES
(1, 7, 'GIVEN', 'Gegebene und gesuchte Groessen identifizieren', 0, 3, 'Keine fachlich relevante Groesse richtig erkannt.', 'Einzelne Groessen, aber zentrale Unterscheidung fehlt.', 'Wesentliche Groessen richtig, geringfuegige Auslassungen.', 'Vollstaendige und sachlich korrekte Trennung von gegeben und gesucht.', 'draft'),
(2, 7, 'REL', 'Funktionale Beziehungen darstellen', 0, 3, 'Keine relevante Beziehung oder grundsaetzlich falsch.', 'Beziehung teilweise erkannt, jedoch fachlich unzureichend.', 'Wesentliche Beziehung korrekt, kleinere Darstellungsfehler.', 'Alle fuer die Aufgabe erforderlichen Beziehungen korrekt und begruendet.', 'draft'),
(3, 7, 'METHOD', 'Loesungsverfahren fachlich begruenden', 0, 3, 'Kein tragfaehiger Ansatz.', 'Ansatz ohne hinreichende Begruendung oder nicht passend.', 'Passender Ansatz mit teilweise nachvollziehbarer Begruendung.', 'Passender Ansatz, logisch nachvollziehbar und fachlich vollstaendig begruendet.', 'draft'),
(4, 7, 'TRANSFER', 'Auf neues Beispiel uebertragen', 0, 3, 'Kein uebertragbarer Ansatz erkennbar.', 'Uebertragung nur mit wesentlicher Hilfe oder grossem Fehler.', 'Selbststaendige, weitgehend korrekte Uebertragung.', 'Selbststaendige, vollstaendige und korrekt begruendete Uebertragung.', 'draft');

