INSERT INTO `rkb2_ch2_claim_review` (`usage_id`, `source_id`, `section_code`, `citation_number`, `claim_fingerprint`, `review_status`, `evidence_uri`, `edition_or_version`, `page_or_section`, `assessment`, `reviewer`, `reviewed_at`, `created_at`, `updated_at`) VALUES
(19, 15, '2.0', 15, '56e4637f9be093ecb993eae83696e91ec4997c6d34296197b827402022cc0370', 'in_review', 'https://doi.org/10.1111/j.1471-1842.2009.00848.x', 'Wiley-Volltext, 26(2), S.91-108; Abstract; Method; Results/Table 1', 'Abstract: Methods/Results; Artikel: Method und Results/Table 1', 'Datenbank-Claim: 14 Reviewtypen und methodischer SALSA-Vergleich. Auf der offiziellen Wiley-Seite direkt belegt. Fachlicher Schlussvergleich mit konkretem deutschen Manuskriptsatz und unabhängige Signatur noch offen.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 08:30:59'),
(20, 16, '2.0', 16, '1f7c9591bf01736c1377833f12c168464a96535d81ca43038b88fdc2afd366ea', 'in_review', 'https://doi.org/10.1016/j.jbusres.2019.07.039', 'Elsevier ScienceDirect, Journal of Business Research 104 (2019), S.333-339; Abstract und Verlagstext', 'Abstract; Abschnitt zur Typologie der Literaturreviews (Detailabgleich noch offen)', 'Datenbank-Claim: Eignung und Transparenz integrativer und weiterer Reviews. Grundrichtung durch Original-Verlagsabstract und publizierte Methodeneinordnung gestützt; genaue Unterabschnitts- und Seitenzuordnung für alle Teilbehauptungen noch fachlich nachprüfen.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 08:30:59'),
(21, 17, '2.0', 17, '74067da70912aadc5d82ce83c84b7f2f2960d18cb8db121a69cfe30b7abd915a', 'in_review', 'https://doi.org/10.1177/1534484305278283', 'SAGE, Human Resource Development Review 4(3), S.356-367; nur offizieller Abstract frei verfügbar', 'Verlagsabstract; Original-Volltext und S.356-367 nicht vollständig prüfbar', 'Datenbank-Claim: integrativer Review als eigenständige Erkenntnis-/Konzeptarbeit. Der eigenständige Erkenntnisbeitrag ist durch den SAGE-Abstract gestützt. Weitergehende Aussagen über Kritik, Synthese und Theorieentwicklung erst nach Originalstellenprüfung übernehmen; VORLÄUFIG.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 08:30:59'),
(22, 18, '2.0', 18, 'c6812bb484c7fad6551758a6b3c8c47c2d20a52e1a534f3e2c7b4774add13621', 'in_review', 'https://doi.org/10.1136/bmj.n71', 'BMJ 372:n71 (2021); PRISMA 2020 Statement, Abstract; 27-item checklist', 'Abstract; Einleitung und Abschnitt zur 27-Item-Checkliste', 'Datenbank-Claim: PRISMA 2020 als Berichtsleitlinie, nicht Zertifizierung einer eigenen integrativen Literaturuntersuchung. Berichtsleitlinie direkt belegt; negative Abgrenzung zu FRZK ist eine sachgerechte methodische Interpretation, keine wörtliche PRISMA-Aussage.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 08:30:59'),
(26, 19, '2.1', 19, '748cb3bf45f1afd33ef9f8c94887826da0a0630b08c575ad59e3813a981670e1', 'in_review', 'https://doi.org/10.1007/s10649-019-09903-9', 'Educational Studies in Mathematics 102(1), 9–28 (2019); Forschungsportal Aarhus; Abstract', 'Universitaets-Forschungsportal: bibliografische Daten und Abstract', 'Niss/Hoeggaard und KOM: Rahmung mathematischer Kompetenzen, Ueberarbeitung der Begriffe. Begriffsrevision durch Verlags-/Universitaetsabstract gestuetzt; detailgenauer Originalstellenabgleich noch ausstehend.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 09:34:32'),
(27, 20, '2.1', 20, 'cc163fe2d8dba0aa399a9aa5913a3f29dc2f7d1c5995ba06925f3bc89cabd8de', 'in_review', 'https://link.springer.com/book/10.1007/978-3-319-45004-9', 'Springer OA Monografie, ICME-13 Topical Surveys, 2016; Kapitel 1–42', 'Springer: Buchoverview und OA-Kapitel, Inhaltsabschnitte zu Modellierungszyklen', 'Deutschsprachige Modellierungsforschung, Modellierungszyklen und divergierende Perspektiven nachvollziehbar. Buch-DOI und Kapitel-DOI (Suffix _1) auseinanderhalten; Einzelaussagen noch abstimmen.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 09:34:32'),
(28, 21, '2.1', 21, 'c5c82c2f439b76c1d3f25f8e31460262cc1803799d4f4816b670cf697151c9ce', 'in_review', 'https://doi.org/10.1007/978-3-319-12688-3_9', 'Springer Proceedings ICME-12, S. 73–96 (2015), Open Access', 'Springer: Abstract, Kapitel/Abschnitte Modellierung, Anwendungen und Unterricht', 'Blum behandelt Wechselspiel reale Welt / Mathematik und qualitaetsvollen Modellierungsunterricht. Die konkrete Reihenfolge von Vereinfachen, Mathematisieren, Loesen und Validieren ist mit Textstellen nachzupruefen.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 09:34:32'),
(29, 22, '2.1', 22, '7aa6445da10766793c9dcb8cfbc79a76a59f913359f59a8f4b24e1f5a64f6ccf', 'in_review', 'https://doi.org/10.1533/9780857099419.5.221', 'ICTMA12 Kapitel 5.1 (2007), ScienceDirect, S. 222–231', 'ScienceDirect: offizieller Abstract, Beschreibung DISUM/Sugarloaf und Abschnittsfolge', 'DISUM, Arbeit von Schuelern und Lehrkraeften an konkreter Modellierungsaufgabe im Originalabstract bestaetigt. DOI endet auf .221, Kapitelzaehlung 5.1, Seiten 222–231; bibliografisch getrennt pruefen.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 09:34:32'),
(30, 23, '2.1', 23, 'bedd6a827d3d5190def03bd0144174e8f64656a46a9b91a08a8afcf443dbb05c', 'in_review', 'https://doi.org/10.1007/BF02655883', 'ZDM 38(2), 86–95 (2006); Artikel-PDF/Abstract zugänglich', 'Originalabstract: kognitionspsychologische Modellierungszyklen und COM2', 'Differenzierung theoretischer und empirischer Modellierungsphasen und schwierige empirische Zuordnung von Aktivitaeten durch Originalabstract gestuetzt; Seitenabgleich erforderlich.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 09:34:32'),
(31, 24, '2.1', 24, '54fce9d8c2accea60ae6c1e0ad820be09a321be1b16e8ab0cd4c29d843f75fe6', 'in_review', 'https://doi.org/10.1007/BF02655885', 'ZDM 38(2), 113–142 (2006); Abstract/Verlagsangaben', 'Originalabstract: Definitionen von Modellierungskompetenzen und empirische Studie', 'Maaß erlaeutert Modellierungskompetenzen und empirische Lern-/Unterrichtsdaten. Genauer Beleg fuer einzelne Fehlerkategorien und Stufen noch anhand Volltext pruefen.', NULL, NULL, '2026-10-20 08:24:12', '2026-10-20 09:34:32'),
