--
-- Tabellenstruktur für Tabelle `source_usage`
--

CREATE TABLE `source_usage` (
  `usage_id` bigint(20) UNSIGNED NOT NULL,
  `source_id` bigint(20) UNSIGNED NOT NULL,
  `section_id` bigint(20) UNSIGNED NOT NULL,
  `usage_type` enum('first_citation','background','definition','theorem','method','historical_context','state_of_research','critique','research_gap','comparison','equation_source','figure_source','table_source','other') NOT NULL,
  `claim_summary` text NOT NULL,
  `exact_location` varchar(255) DEFAULT NULL,
  `is_first_mention` tinyint(1) NOT NULL DEFAULT 0,
  `citation_checked` tinyint(1) NOT NULL DEFAULT 0,
  `notes` text DEFAULT NULL,
  `created_revision_id` bigint(20) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Daten für Tabelle `source_usage`
--

INSERT INTO `source_usage` (`usage_id`, `source_id`, `section_id`, `usage_type`, `claim_summary`, `exact_location`, `is_first_mention`, `citation_checked`, `notes`, `created_revision_id`) VALUES
(1, 7, 2, 'first_citation', 'DOCX-Originaltext: „In der Physik wird zunehmend diskutiert, dass Raumzeit nicht fundamental, sondern emergent ist“', 'Kapitel 1, DOCX-Absatz 3, [7]', 1, 0, 'Erstnennung nach Format (vollständige Quelle)[Nr.]. Der zitierte Satz stammt aus dem Dissertationsdokument und nicht wortgetreu aus der Literaturquelle; Beleginhalt noch nicht geprüft.\n[DEEP RESEARCH 2026-10-17] Rovelli diskutiert, dass bestimmte verbreitete Vorstellungen einer einheitlichen und universellen Zeit auf fundamentaler Ebene nicht direkt gelten. Dies belegt keine FRZK-Initialisierung aus der leeren Menge.\nZitattyp: NUR_INDIREKT\nFundstelle: Penguin Random House, Buchbeschreibung 2018; Physics Today, Autoreninterview (andere Quelle)\nQuelle der Recherche: https://www.penguinrandomhouse.com/books/551483/the-order-of-time-by-carlo-rovelli/9780735216129\nEinschraenkung: Buchseite S. 36 ff. nicht anhand Originalausgabe geprüft; kein direkter Schluss auf Emergenz geometrischer Achsen.', 2),
(2, 3, 2, 'first_citation', 'DOCX-Originaltext: „In der Systemtheorie und Kybernetik stehen Selbstreferenz, Beobachtung zweiter Ordnung und autopoietische Strukturen im Vordergrund“', 'Kapitel 1, DOCX-Absatz 4, [3]', 1, 0, 'Erstnennung nach Format (vollständige Quelle)[Nr.]. Der zitierte Satz stammt aus dem Dissertationsdokument und nicht wortgetreu aus der Literaturquelle; Beleginhalt noch nicht geprüft.\n[DEEP RESEARCH 2026-10-17] Von Foersters Werk versammelt kybernetische Beiträge über Beobachtung, erkenntnistheoretische Selbstbezüglichkeit und selbstorganisierende Systeme.\nZitattyp: NUR_INDIREKT\nFundstelle: Open Library, Katalogeintrag für die Ausgabe 1981, Seitenangabe offen\nQuelle der Recherche: https://openlibrary.org/books/OL13550910M/Observing_systems\nEinschraenkung: Nur Werkzuordnung und Themenkatalog geprüft; kein wörtliches Buchzitat und keine Belegseite verifiziert.', 2),
(3, 4, 2, 'first_citation', 'DOCX-Originaltext: „In der Systemtheorie und Kybernetik stehen Selbstreferenz, Beobachtung zweiter Ordnung und autopoietische Strukturen im Vordergrund“', 'Kapitel 1, DOCX-Absatz 4, [4]', 1, 0, 'Erstnennung nach Format (vollständige Quelle)[Nr.]. Der zitierte Satz stammt aus dem Dissertationsdokument und nicht wortgetreu aus der Literaturquelle; Beleginhalt noch nicht geprüft.\n[DEEP RESEARCH 2026-10-17] Maturana und Varela behandeln lebende Systeme, Autopoiesis, strukturelle Kopplung und die biologischen Grundlagen des Erkennens. Dies deckt nicht automatisch von Foersters Beobachtung zweiter Ordnung ab.\nZitattyp: NUR_INDIREKT\nFundstelle: Google Books, Inhaltsverzeichnis der Ausgabe 1987: The Organization of Living Things ab S. 33\nQuelle der Recherche: https://books.google.com/books/about/The_Tree_of_Knowledge.html?id=8anuAAAAMAAJ\nEinschraenkung: Autopoiesis in Biologie nicht ohne Argument auf mathematische oder didaktische FRZK-Operatoren übertragbar.', 2),
(4, 5, 2, 'first_citation', 'DOCX-Originaltext: „In der Didaktik wiederum wird verstärkt nach Modellen gesucht, die Lernprozesse nicht linear, sondern komplex, rekursiv und reflexiv beschreiben können“', 'Kapitel 1, DOCX-Absatz 4, [5]', 1, 0, 'Erstnennung nach Format (vollständige Quelle)[Nr.]. Der zitierte Satz stammt aus dem Dissertationsdokument und nicht wortgetreu aus der Literaturquelle; Beleginhalt noch nicht geprüft.\n[DEEP RESEARCH 2026-10-17] Reinmann beschreibt Design-Based Research als iterative und kontextsensitive Verbindung von Gestaltung, Forschung, Reflexion und Verbesserung der Bildungspraxis.\nZitattyp: DIREKT_GEPRUEFT\nLiteratur-Kurzzitat: \"Entwicklung und Forschung finden in kontinuierlichen Zyklen von Gestaltung, Durchführung, Analyse und Re-Design statt\"\nFundstelle: Reinmann (2005), Unterrichtswissenschaft 33(1), S. 62, Abschnitt Forschungsstrategisches und -methodisches Vorgehen\nQuelle der Recherche: https://www.pedocs.de/volltexte/2013/5787/pdf/UntWiss_2005_1_Reinmann_Innovation_ohne_Forschung.pdf\nEinschraenkung: Stützt iterative Designforschung, beweist aber nicht allgemein emergente Raumzeitstrukturen von Lernprozessen.', 2),
